  'AI চালু থাকলে Anthropic-এ যায়: আপনার বলা বা লেখা বাক্য, টাকার হিসাবের সারাংশ (নাম ও অঙ্ক), রিমাইন্ডার, কাজ, নোট, অভ্যাসের নাম, বিশেষ দিন, ডকুমেন্টের নাম আর “মনে রেখো” কথাগুলো — যাতে আপনার জিনিস নিয়ে ঠিক উত্তর দিতে পারে। কখনো যায় না: পাসওয়ার্ড ও ভল্ট, PIN/OTP/পাসওয়ার্ড থাকা নোট, ওষুধ, স্বাস্থ্যের মাপ, ওষুধ-ডাক্তার-অসুখের কথা থাকা রিমাইন্ডার-কাজ-নোট, ফোন-কার্ড-NID নম্বর, ইমেইল আর অন্য অ্যাপের মেসেজ।': 'With the AI on, Anthropic receives: what you say or type, a money summary (names and amounts), reminders, tasks, notes, habit names, special days, document names and your “remember” notes — so it can answer about your things. Never sent: passwords and the vault, notes with PINs/OTPs/passwords, medicines, health readings, reminders/tasks/notes about medicine, doctors or illness, phone/card/ID numbers, emails and messages from other apps.',
  'AI চালু থাকলে আপনার বলা বাক্য, টাকার হিসাবের সারাংশ, রিমাইন্ডার, কাজ আর নোট Anthropic-এ যায়, যাতে আপনার জিনিস নিয়ে প্রশ্নের ঠিক উত্তর দিতে পারে; পাসওয়ার্ড, ভল্ট, PIN, ফোন নম্বর বা গোপন কোড থাকা নোট কখনো যায় না।': 'With the AI on, what you say, a summary of your money, reminders, tasks and notes are sent to Anthropic so it can answer questions about your things accurately. Passwords, the vault, PINs, phone numbers and notes with secret codes are never sent.',
  'AI চালু থাকলে আপনার বলা বাক্য, লেনদেনের মানুষের নাম আর টাকার হিসাবের সারাংশ Anthropic-এ যায়; পাসওয়ার্ড, ভল্ট, PIN, ফোন নম্বর, নোট বা কাজের লেখা যায় না।': 'With the AI on, what you say, the names of people you deal with and a summary of your money are sent to Anthropic. Passwords, the vault, PINs, phone numbers, notes and task text are never sent.',
  'AI চালু থাকলে শুধু আপনার বলা বা লেখা বাক্য আর টাকার হিসাবের সারাংশ (নাম ও অঙ্ক) Anthropic-এ যায়। রিমাইন্ডার, কাজ, নোট, পাসওয়ার্ড, ভল্ট, ফোন-কার্ড-NID নম্বর বা অন্য অ্যাপের মেসেজ যায় না।': 'With the AI on, only what you say or type and a money summary (names and amounts) are sent to Anthropic. Reminders, tasks, notes, passwords, the vault, phone/card/ID numbers and messages from other apps are not.',
