  'NID, পাসপোর্ট, জমির কাগজ, প্রেসক্রিপশন, ওয়ারেন্টি, পরিবারের ছবি — ফোল্ডারে, তালাবদ্ধ। একসাথে অনেক ছবি রাখা যায়, পরে নাম-বিবরণ বলে খোঁজা যায়।': 'NID, passport, land deeds, prescriptions, warranties, family photos — in locked folders. Add many photos at once and find them later by name or description.',
  'NID, পাসপোর্ট, দলিল — কোনো সীমা নেই': 'NID, passport, deeds — unlimited',
