  'PIN মেলেনি। আর {0} বার চেষ্টা করা যাবে।': 'Incorrect PIN. {0} attempts left.',
  'PIN শুধু এই ফোনে, এনক্রিপ্ট করে রাখা হয়। ভুলে গেলে আঙুলের ছাপ বা Google Drive ব্যাকআপের পাসওয়ার্ড দিয়ে নতুন PIN দেওয়া যাবে।': 'Your PIN is stored only on this phone, encrypted. If you forget it, you can set a new one with your fingerprint or your Google Drive backup password.',
  'PIN শুধু এই ফোনে, এনক্রিপ্ট করে রাখা হয়। ভুলে গেলে আঙুলের ছাপ বা একই Google অ্যাকাউন্ট দিয়ে নতুন PIN দেওয়া যাবে।': 'Your PIN is stored only on this phone, encrypted. If you forget it, you can set a new one with your fingerprint or the same Google account.',
  'PIN শুধু এই ফোনে, এনক্রিপ্ট করে রাখা হয়। ভুলে গেলে তথ্য ফেরত আনা যাবে না — ব্যাকআপ রাখুন।': 'Your PIN is stored only on this phone, encrypted. If you forget it, your data can’t be recovered — keep a backup.',
  'WhatsApp খোলা গেল না': 'Couldn’t open WhatsApp',
  'WhatsApp, SMS, বিকাশের মেসেজ থেকে নিজে হিসাব আর কাজ বানায়': 'Creates records and tasks from WhatsApp, SMS and bKash messages',
  'WhatsApp, Telegram, imo, Messenger, Gmail, SMS-এ নতুন মেসেজ এলে সহকারী নোটিফিকেশন থেকে তা পড়বে, আর মিটিং, টাকা চাওয়া, বিল, উত্তর দেওয়ার মতো কাজগুলো আলাদা করে দেখাবে। এক চাপে রিমাইন্ডার বা কাজ বানাতে, এখান থেকেই উত্তর দিতে পারবেন।': 'When a new WhatsApp, Telegram, imo, Messenger, Gmail or SMS message arrives, the assistant reads it from the notification and picks out meetings, payment requests, bills and questions to answer. Create a reminder or task in one tap, and reply from here.',
  'WhatsApp, Telegram, imo, Messenger, Gmail, SMS-এর নতুন মেসেজ পড়ে মিটিং, টাকা চাওয়া, বিল, উত্তর দেওয়ার কাজ আলাদা করে; এক চাপে রিমাইন্ডার, এখান থেকেই উত্তর।': 'Reads new WhatsApp, Telegram, imo, Messenger, Gmail and SMS messages and picks out meetings, payment requests, bills and pending replies — set a reminder in one tap and reply from here.',
  'WhatsApp-এ পাঠান': 'Send on WhatsApp',
  'Wi-Fi-এর কোনো তথ্য এখনো রাখা হয়নি। চাইলে এখনই রেখে দিতে পারেন।': 'No Wi-Fi details saved yet. You can add them now.',
  'Wi-Fi-এর কোনো তথ্য নেই। পাসওয়ার্ড ভল্টে তথ্যটি যুক্ত করতে পারেন — পরে জিজ্ঞেস করলে আঙুলের ছাপ নিয়ে দেখাবো।': 'No Wi-Fi details found. Add them to the Password Vault — when you ask, I’ll show them after you verify with your fingerprint.',
