  'অনেক কিছু পারি — কাজের তালিকা, সময়মতো মনে করানো, ফোন-মেসেজ, ধার-দেনা আর আয়-ব্যয়ের হিসাব, নোট, কাগজপত্র, পাসওয়ার্ড, স্বাস্থ্য আর বিশেষ দিন। যেকোনো পাতাও খুলে দিতে পারি — যেমন বলুন “নোট খোলো”। পুরো তালিকা নিচে দিলাম।': 'A lot — tasks, timely reminders, calls and messages, loans and income & expenses, notes, documents, passwords, health and special days. I can also open any page — say “Open Notes”. The full list is below.',
  'অনেক দিন না খুললে': 'If you haven’t opened the app in a while',
  'অনেকক্ষণ কিছু শুনিনি, তাই মাইক বন্ধ রাখলাম। বলতে চাইলে “বলুন” চাপুন।': 'I didn’t hear anything for a while, so I turned off the mic. Tap “Speak” when you’re ready.',
