  'অন্য অ্যাপের কোনো মেসেজের তথ্য নেই। “মেসেজ” পাতায় অনুমতি দিয়ে অ্যাপগুলো বেছে দিন — তারপর WhatsApp, imo, Gmail-এর নতুন মেসেজ থেকে কাজের কথা বের করে দেবো।': 'No messages from other apps yet. Grant permission on the Messages page and choose the apps — I’ll then pick out action items from new WhatsApp, imo and Gmail messages.',
