  'ফোন সমান করে বা সামনে খাড়া করে — যেভাবে সুবিধা ধরুন; ফোনের মাথা যেদিকে, দিক সেটাই। প্রথমবার ফোনটা বাতাসে কয়েকবার ৮ আঁকার মতো ঘোরান। লোহা, চুম্বক, স্পিকার, ল্যাপটপ বা চুম্বকওয়ালা কভার থেকে দূরে রাখুন — এগুলো দিক বদলে দেয়। কিবলার দিক আপনার জেলার হিসেবে; মসজিদের দিক মিলিয়ে নেওয়া ভালো।': 'Hold the phone flat or upright in front of you, whichever is easier; it shows where the top of the phone points. The first time, move the phone in a figure-8 a few times. Keep it away from metal, magnets, speakers, laptops and magnetic cases — they distort the reading. The qibla is calculated from your district; it’s best to confirm with a local mosque.',
  'উ': 'N',
  'পূ': 'E',
  'দ': 'S',
  'প': 'W',
  'উত্তর': 'North',
  'উত্তর-পূর্ব': 'Northeast',
  'পূর্ব': 'East',
  'দক্ষিণ-পূর্ব': 'Southeast',
  'দক্ষিণ': 'South',
  'দক্ষিণ-পশ্চিম': 'Southwest',
  'পশ্চিম': 'West',
  'উত্তর-পশ্চিম': 'Northwest',
  'প্রবাদ': 'Proverb',
  'বেঞ্জামিন ফ্র্যাংকলিন, “দ্য ওয়ে টু ওয়েলথ”': 'Benjamin Franklin, “The Way to Wealth”',
  'সূরা বনী ইসরাঈল, ১৭:২৬-২৭': 'Surah Al-Isra, 17:26-27',
  'সূরা আল-ফুরকান, ২৫:৬৭': 'Surah Al-Furqan, 25:67',
  'আয় বুঝে ব্যয় করো।': 'Spend according to what you earn.',
  'খরচের পর যা থাকে তা জমাবেন না; জমানোর পর যা থাকে, তা খরচ করুন।': 'Don’t save what is left after spending; spend what is left after saving.',
  'ছোট খরচগুলোকে অবহেলা করবেন না — ছোট একটা ফুটোই বড় জাহাজ ডুবিয়ে দিতে পারে।': 'Beware of little expenses; a small leak will sink a great ship.',
  'আর তোমরা অপচয় কোরো না। নিশ্চয়ই অপচয়কারীরা শয়তানের ভাই।': 'And do not spend wastefully. Indeed, the wasteful are brothers of the devils.',
  'আর যারা ব্যয় করার সময় অপব্যয় করে না, কৃপণতাও করে না — বরং এ দুয়ের মাঝামাঝি থাকে।': 'And those who, when they spend, are neither wasteful nor stingy, but hold a just balance between the two.',
  'বিন্দু বিন্দু জলে সিন্ধু হয় — প্রতিদিনের অল্প সঞ্চয়ই একদিন বড় সম্বল।': 'Little drops make an ocean — a little saved every day becomes a real reserve.',
  'যা দরকার তা কিনুন; যা ভালো লাগে, তা কেনার আগে এক দিন অপেক্ষা করুন।': 'Buy what you need; for what you merely like, wait a day first.',
  'বেতন হাতে আসার দিনই আগে সঞ্চয়ের অংশটা সরিয়ে রাখুন — পরে আর থাকে না।': 'Set aside your savings the day your salary arrives — otherwise it’s gone.',
  'তিন থেকে ছয় মাসের খরচের সমান টাকা বিপদের জন্য আলাদা রাখুন।': 'Keep three to six months of expenses aside for emergencies.',
  'ধার করে শখ মেটানো মানে ভবিষ্যতের আয় আজ খরচ করে ফেলা।': 'Borrowing for wants is spending tomorrow’s income today.',
  'প্রতিটা খরচ লিখে রাখুন — না লিখলে বোঝাই যায় না টাকা কোথায় যায়।': 'Write down every expense — otherwise you’ll never see where the money goes.',
  'আয়ের মোটামুটি অর্ধেক প্রয়োজনে, এক-তৃতীয়াংশের কম শখে, আর অন্তত এক-পঞ্চমাংশ সঞ্চয়ে।': 'About half your income on needs, under a third on wants, and at least a fifth saved.',
  'দামি জিনিস নয়, দরকারি জিনিস কিনুন।': 'Buy what is useful, not what is expensive.',
  'বাইরে খাওয়া মাঝে মাঝে আনন্দ; প্রতিদিন হলে বড় খরচ।': 'Eating out now and then is a treat; every day, it’s a big expense.',
  'ঋণ নেওয়ার আগে ভাবুন — কিস্তি দেওয়ার দিনও আসবে।': 'Think before borrowing — installment days will come too.',
  'অন্যকে দেখে খরচ করবেন না; নিজের আয় দেখে করুন।': 'Don’t spend based on others; spend based on your income.',
  'ছাড় দেখে কেনা নয় — দরকার থাকলে তবেই ছাড় কাজে লাগে।': 'Don’t buy just because of a discount — it only helps if you need the item.',
  'মাসের শুরুতেই একটা খরচের সীমা ঠিক করুন, শেষে মিলিয়ে দেখুন।': 'Set a spending limit at the start of the month and check it at the end.',
  'পাওনা টাকা সময়মতো তুলুন, দেনা সময়মতো শোধ করুন — সম্পর্ক আর হিসাব দুটোই ভালো থাকে।': 'Collect what you’re owed and repay what you owe on time — both relationships and finances stay healthy.',
  'শিক্ষা আর স্বাস্থ্যে খরচ খরচ নয়, বিনিয়োগ।': 'Spending on education and health isn’t an expense — it’s an investment.',
  'অল্প আয়েও সঞ্চয় সম্ভব — শুরুটা যত ছোটই হোক।': 'Saving is possible even on a small income — however small the start.',
  'বিল আর কিস্তির তারিখ মনে রাখলে জরিমানার টাকা বাঁচে।': 'Remembering bill and installment dates saves late fees.',
  'যে খরচ না করলেও চলে, সপ্তাহে একবার তার তালিকা করুন — অর্ধেক কমালেই অনেক বাঁচে।': 'Once a week, list the expenses you could do without — halving them saves a lot.',
  'হঠাৎ পাওয়া টাকা হঠাৎ খরচ নয় — আগে একটা অংশ জমা রাখুন।': 'Unexpected money isn’t for unexpected spending — save part of it first.',
  'দান করলে সম্পদ কমে না — নিজের সামর্থ্য বুঝে নিয়মিত দিন।': 'Giving doesn’t make you poorer — give regularly, as you can afford.',
  'মোবাইলে কেনাকাটা সহজ, তাই সাবধানও হতে হয় বেশি।': 'Shopping on your phone is easy, so be extra careful.',
  'ধীরে ধীরে জমানো টাকা হঠাৎ পাওয়া টাকার চেয়ে বেশি দিন থাকে।': 'Money saved slowly lasts longer than money that came suddenly.',
  'পরিবারের সবাই মিলে বাজেট করলে খরচ কমানো সহজ হয়।': 'Budgeting together as a family makes cutting costs easier.',
  'টাকা ভালো ভৃত্য, কিন্তু খারাপ মালিক।': 'Money is a good servant but a bad master.',
  'আজকের ছোট সংযম কালকের বড় স্বস্তি।': 'A little restraint today brings great relief tomorrow.',
  'আপনি ‘{0}’ নামে আলাদা হিসাব চেয়েছিলেন — অন্যান্য হিসাবে খুলে দিই?': 'You asked for a project called ‘{0}’ — shall I create it under Projects?',
  'হ্যাঁ, খুলে দাও': 'Yes, open it',
  'দুঃখিত, আগে ঠিক উত্তর দিইনি। আপনি ‘{0}’ নামে আলাদা হিসাব চেয়েছেন — অন্যান্য হিসাবে খুলে দিই?': 'Sorry, I didn’t answer that correctly. You asked for a project called ‘{0}’ — shall I create it under Projects?',
  'খুলে দেবো কিনা — হ্যাঁ বা না বলুন।': 'Shall I create it? Say yes or no.',
  'আচ্ছা, খুললাম না।': 'OK, not created.',
  '{0} {1}-এ': 'in {0} {1}',
  'ঠিক আছে, {0}টা কাজ {1} রাখলাম।': 'OK, {0} tasks set for {1}.',
  '‘{0}’ নামে হিসাব আগেই খোলা আছে — অন্যান্য হিসাবে পাবেন।': 'A project called ‘{0}’ already exists — find it under Projects.',
  '‘{0}’ নামে আলাদা কোনো হিসাব এখনো নেই। অন্যান্য হিসাবে ‘{0}’ খুলে দিই?': 'There’s no project called ‘{0}’ yet. Create ‘{0}’ under Projects?',
  '“{0}” খাতে আজ কোনো খরচ লেখা নেই। রাখতে চাইলে বলুন, যেমন “{0} {1} টাকা খরচ”।': 'No expenses recorded under “{0}” today. To add one, say e.g. “{0} {1} taka spent”.',
  'হ্যাঁ, {0} — {1} টাকা লেখা আছে ({2})।': 'Yes, {0} — ৳{1} recorded ({2}).',
  'না — {0} লেখা আছে {1} টাকা ({2}), {3} নয়। ভুল হলে বলুন “{0} {3} টাকা হবে”।': 'No — {0} is recorded as ৳{1} ({2}), not {3}. If that’s wrong, say “{0} should be {3} taka”.',
  '‘{0}’ নামে হিসাব আগেই খোলা আছে।': 'A project called ‘{0}’ already exists.',
  'খুলে দিলাম — অন্যান্য হিসাবে ‘{0}’। এখন বলুন, যেমন “মাহি ২০০০ টাকা দিয়েছে, {0} হিসাবে”।': 'Created the project ‘{0}’. Now say, e.g., “Mahi gave 2000 taka, in {0}”.',
  'কোন কাজগুলোর কথা বলছেন, খুঁজে পেলাম না — যেমন বলুন “কালকের প্রতিটি কাজের রিমাইন্ডার দাও, সকাল ৯টায়”।': 'I couldn’t find which tasks you mean — say e.g. “a reminder for each of tomorrow’s tasks at 9 am”.',
  'যেগুলোর নির্দিষ্ট দিন নেই, সেগুলো মাস/বছরের প্রথম দিনে রাখলাম।': 'Tasks without a set day are placed on the first day of their month or year.',
  '{0}টার সময় পেরিয়ে গেছে, ওগুলোতে দিইনি।': '{0} had already passed, so no reminder was set for them.',
  'ঠিক আছে, {0}টা কাজের রিমাইন্ডার {1}-এ রাখলাম।': 'OK, reminders set for {0} tasks at {1}.',
  '“বাজারের কাজটা মুছে দাও”': '“remove the shopping task”',
  '“মিটিংয়ের রিমাইন্ডারটা মুছে দাও”': '“remove the meeting reminder”',
  '“ওয়াইফাইয়ের নোটটা মুছে দাও”': '“remove the wifi note”',
  '“রহিমের ৫০০ টাকার লেনদেনটা মুছে দাও”': '“remove Rahim’s ৳500 entry”',
  'কোনটা {0}, খুঁজে পেলাম না। নাম বা তারিখ বলে আরেকবার বলুন — যেমন {1}।': 'I couldn’t find which one to {0}. Say it again with its name or date — e.g. {1}.',
  'দুঃখিত। শেষে রেখেছি: {0}। কোনটা ভুল — নাম, তারিখ, না পুরোটাই? বলুন কী হবে, অথবা “ফিরিয়ে নাও” বললে ওটা সরিয়ে দেব।': 'Sorry. The last item I saved: {0}. What’s wrong — the name, the date, or everything? Tell me, or say “undo” and I’ll reverse it.',
  'কোন তারিখ? যেমন “১০ তারিখে” ({0})।': 'Which date? E.g., “the 10th” ({0}).',
  'রিমাইন্ডারটা রাখা হয়েছে ({0}), কিন্তু ফোনে সেট করা যায়নি — তাই এখনো বাজবে না। অ্যাপটা একবার বন্ধ করে খুলুন; তবু না হলে রিমাইন্ডার পাতা থেকে আবার চালু করুন।': 'The reminder is saved ({0}), but the phone couldn’t schedule it — so it won’t ring yet. Close and reopen the app; if it still fails, turn it on again from the Reminders page.',
  'ফিরিয়ে নেওয়ার মতো শেষ কোনো পরিবর্তন পেলাম না — মুছে ফেলা জিনিস “রিসাইকেল বিন” থেকে ফেরত আনা যায়।': 'There’s no recent change to undo — deleted items can be restored from Trash.',
  'ফিরিয়ে নিলাম — শেষ পরিবর্তনের আগের মতো আছে।': 'Undone — everything is as it was before the last change.',
  'ওই অংশে কিছু বদলাইনি।': 'Nothing was changed for that part.',
  ' তালিকার বাকি {0}টা আছে।': ' {0} items remain on that list.',
  ' তবে ফোনে সেট করা যায়নি — এখনো বাজবে না।': ' But the phone couldn’t schedule it — it won’t ring yet.',
  'এই {0}টা কাজ {1} {2}-এর, নির্দিষ্ট দিন নেই। {1} মাসের কত তারিখে {3}-এ মনে করাব?': 'These {0} tasks are for {1} {2}, with no set day. Which day of {1} should I remind you at {3}?',
  'তবে ফোনে সেট করা যায়নি — এখনো বাজবে না।': 'But the phone couldn’t schedule it — it won’t ring yet.',
  '{0} তো পার হয়ে গেছে — কিছু রাখিনি।': '{0} has already passed — nothing was saved.',
  '“{0}”-এর রিমাইন্ডার রাখা হয়েছে ({1}), কিন্তু ফোনে সেট করা যায়নি — তাই এখনো বাজবে না। অ্যাপটা একবার বন্ধ করে খুলুন; তবু না হলে রিমাইন্ডার পাতা থেকে আবার চালু করুন।': 'The reminder for “{0}” is saved ({1}), but the phone couldn’t schedule it — so it won’t ring yet. Close and reopen the app; if it still fails, turn it on again from the Reminders page.',
  '“{0}” কাজটা কোথায় ভাগ হবে বুঝতে পারিনি — কাজগুলোর নাম আলাদা করে বলুন, যেমন “মাছ কেনা, চাল কেনা”।': 'I couldn’t tell how to split “{0}” — say the tasks one by one, e.g. “buy fish, buy rice”.',
  'ঠিক আছে — একটার বদলে {0}টা আলাদা কাজ রাখলাম{1}।': 'OK — saved {0} separate tasks instead of one{1}.',
  '{0} মাসে {1} তারিখ নেই — মাসটা {2} দিনের। কোন তারিখ বোঝাচ্ছেন — {2} {0}, নাকি অন্য দিন?': '{0} has no {1}th — it has {2} days. Which date do you mean — {0} {2}, or another day?',
  '{0} টাকা নিয়ে গিয়েছিলেন, খরচ {1} টাকা — হাতে থাকার কথা {2} টাকা।': 'You took ৳{0} and spent ৳{1} — you should have ৳{2} left.',
  '{0} টাকা নিয়ে গিয়েছিলেন, কিন্তু খরচ বলেছেন {1} টাকা — {2} টাকা বেশি। কোনো অঙ্ক ভুল হলে বলুন।': 'You took ৳{0} but said you spent ৳{1} — ৳{2} more. Let me know if an amount is wrong.',
