  'এই ফোনে আঙুলের ছাপ চালু নেই': 'Fingerprint isn’t set up on this phone',
  'এই ফোনে আঙুলের ছাপ বা Google অ্যাকাউন্ট যুক্ত নেই, তাই PIN ছাড়া খোলা যাবে না — যাতে ফোন অন্যের হাতে গেলেও আপনার তথ্য নিরাপদ থাকে। Google Drive-এ ব্যাকআপ থাকলে: অ্যাপ মুছে আবার ইনস্টল করুন, একই Google অ্যাকাউন্টে লগইন করে সব ফিরিয়ে আনুন।': 'This phone has no fingerprint or Google account linked in the app, so it can’t be opened without the PIN — keeping your data safe if the phone is in someone else’s hands. If you have a Google Drive backup: reinstall the app, sign in with the same Google account and restore everything.',
  'এই ফোনে আঙুলের ছাপ বা ব্যাকআপ-পাসওয়ার্ড চালু নেই, তাই PIN ছাড়া খোলা যাবে না — যাতে ফোন অন্যের হাতে গেলেও আপনার তথ্য নিরাপদ থাকে। Google Drive-এ ব্যাকআপ থাকলে: অ্যাপ মুছে আবার ইনস্টল করুন, একই Google অ্যাকাউন্টে লগইন করে ব্যাকআপ-পাসওয়ার্ড দিয়ে সব ফিরিয়ে আনুন।': 'Fingerprint and backup password aren’t set up on this phone, so it can’t be opened without the PIN — keeping your data safe if the phone is in someone else’s hands. If you have a Google Drive backup: reinstall the app, sign in with the same Google account and restore everything with the backup password.',
