  'এই ফোনে “Autostart / Auto-launch / Background” থেকে My Assistant চালু করতে হয়, নইলে ফোন বন্ধ-চালুর পর রিমাইন্ডার আসে না': 'On this phone, allow My Assistant under “Autostart / Auto-launch / Background”, otherwise reminders stop after a restart',
  'এই ফোনের কিছু সেটিং রিমাইন্ডার থামিয়ে দিতে পারে। এক মিনিটে ঠিক করে নেবেন?': 'Some settings on this phone can block reminders. Fix them in a minute?',
  'এই ফোনের ভয়েস সেবায় বাংলা চালু নেই। Google অ্যাপ → Settings → Voice → Languages থেকে “বাংলা (বাংলাদেশ)” যোগ করুন।': 'Bangla isn’t enabled in this phone’s voice service. Add “বাংলা (বাংলাদেশ)” in the Google app → Settings → Voice → Languages.',
  'এই ফোনের সুরক্ষিত চাবি দিয়ে তথ্যের ফাইল খোলা যাচ্ছে না। অ্যাপ নতুন করে ইনস্টল হলে বা ফোনের নিরাপত্তা বদলালে এমন হতে পারে। পুরনো ফাইলটা মুছে ফেলা হয়নি। ব্যাকআপ থাকলে নিচ থেকে ফিরিয়ে আনুন — পুরনো ফাইলটা আলাদা করে রাখা থাকবে।': 'Your data file can’t be opened with this phone’s secure key. This can happen after reinstalling the app or changing the phone’s security settings. The old file hasn’t been deleted. If you have a backup, restore it below — the old file will be kept aside.',
  'এই ফোনের সুরক্ষিত চাবি দিয়ে তথ্যের ফাইল খোলা যাচ্ছে না। অ্যাপ নতুন করে ইনস্টল হলে বা ফোনের নিরাপত্তা বদলালে এমন হতে পারে। ব্যাকআপ থাকলে অ্যাপের ডেটা মুছে নতুন করে শুরু করে ব্যাকআপ ফিরিয়ে আনুন।': 'Your data file can’t be opened with this phone’s secure key. This can happen after reinstalling the app or changing the phone’s security settings. If you have a backup, clear the app’s data, start again and restore the backup.',
