  'এক চান্দ্র বছর ধরে নিসাব পরিমাণ সম্পদ থাকলে মোট সম্পদের ২.৫% যাকাত। এটা আনুমানিক হিসাব — নিশ্চিত হতে আলেমের পরামর্শ নিন।': 'If you’ve held at least the nisab for a lunar year, zakat is 2.5% of your total wealth. This is an estimate — consult a scholar to be sure.',
  'এক চান্দ্র বছর ধরে নিসাব পরিমাণ সম্পদ থাকলে মোট সম্পদের ২.৫% যাকাত। এটা আনুমানিক হিসাব — নিশ্চিত হতে আলেমের পরামর্শ নিন। মুখেও জিজ্ঞেস করা যায়: “আমার যাকাত কত?”': 'If you’ve held nisab-level wealth for a lunar year, zakat is 2.5%. This is an estimate — consult a scholar to be sure. You can also ask aloud: “How much is my zakat?”',
