  'একই দিনে একই খাতে একই টাকার দুটো খরচ পাইনি — কিছু মুছিনি। কোনটা দুবার হয়েছে, খাত আর টাকা বলে আবার বলুন।': 'No two expenses with the same amount, category and day were found — nothing deleted. Say which one was entered twice, with its category and amount.',
