  'এখানে আলাদা ধরনের জিনিস আছে ({0}) — একসাথে করছি না। কোনটা, নম্বর বলুন — যেমন “১”।': 'These are different kinds of items ({0}) — I won’t process them together. Say which one by number — e.g. “1”.',
