  'পাসওয়ার্ড, PIN বা ব্যক্তিগত নম্বর লিখবেন না। শুধু এখানে যা লিখবেন বা যুক্ত করবেন সেটুকু আর অ্যাপের সংস্করণ যাবে — আপনার অন্য কোনো তথ্য না।': 'Don’t include passwords, PINs or personal numbers. Only what you write or attach here and the app version are sent — none of your other data.',
  'পাসওয়ার্ড, PIN বা ব্যক্তিগত নম্বর লিখবেন না। শুধু এখানে যা লিখবেন সেটুকু আর অ্যাপের সংস্করণ যাবে — আপনার অন্য কোনো তথ্য না।': 'Don’t include passwords, PINs or personal numbers. Only what you write here and the app version are sent — none of your other data.',
