  'মুখে বললে কথাকে লেখায় রূপান্তর করে ফোনের নিজের ভয়েস সেবা (সাধারণত Google)। সেজন্য আপনার কণ্ঠ ইন্টারনেটে Google-এর কাছে যেতে পারে — AI বন্ধ থাকলেও। না চাইলে লিখে ব্যবহার করুন।': 'Speech is converted to text by your phone’s voice service (usually Google), so your voice may be sent to Google over the internet — even with the AI off. You can type instead if you prefer.',
