  'মুখে বলে সব কাজ, আয়-ব্যয় ও ধার-দেনা (২০ জন), তাগাদার মেসেজ, কাজের তালিকা, ২০টা চালু রিমাইন্ডার, অ্যালার্ম, ক্যালেন্ডার ও নামাজের সময়, নোট, ৩০টা ডকুমেন্ট, পরিবারের সবার স্বাস্থ্য, শিশুর টিকা, ওষুধের রিমাইন্ডার, অভ্যাস, যাকাতের হিসাব, সঞ্চয়, ১টা দোকান, ১টা অন্যান্য হিসাব, ১০টা পাসওয়ার্ড, নিজে চাপলে Google Drive-এ ব্যাকআপ আর নতুন ফোনে সব ফিরিয়ে আনা। আপনার রাখা কোনো তথ্য কখনো তালাবদ্ধ হবে না।': 'Everything by voice, income & expenses and loans (20 people), payment reminder messages, tasks, 20 active reminders, alarms, calendar and prayer times, notes, 30 documents, health records for the whole family, child vaccinations, medicine reminders, habits, zakat, savings, 1 shop, 1 project, 10 passwords, manual Google Drive backup and full restore on a new phone. Nothing you save is ever locked.',
