  'মেয়াদের কোনো তথ্য নেই। ডকুমেন্টসে কাগজটি রেখে মেয়াদের তারিখ দিলে শেষ হওয়ার আগে মনে করিয়ে দেবো।': 'No expiry information. Save the document in Documents with its expiry date and I’ll remind you before it expires.',
