  'মেসেজ পড়া বন্ধ রাখা আছে। উপরের ডান কোণের বোতাম থেকে চালু করুন।': 'Reading messages is off. Turn it on with the button at the top right.',
  'মেসেজ শুধু এই ফোনে থাকে — কোনো সার্ভার বা AI-তে যায় না। OTP, পিন, পাসওয়ার্ডের মেসেজ রাখা হয় না। কোন অ্যাপ পড়বে আপনি বেছে দেবেন, যেকোনো সময় বন্ধ করা যায়। আগের পুরনো চ্যাট পড়া যায় না, শুধু নতুন আসা মেসেজ।': 'Messages stay on this phone — never sent to a server or the AI. OTP, PIN and password messages are never saved. You choose which apps are read and can turn it off any time. Only new messages are read, not old chats.',
  'মেসেজগুলো শুধু এই ফোনে, তালাবদ্ধ অবস্থায় থাকে; কোনো সার্ভার বা AI-তে যায় না। OTP, পিন বা পাসওয়ার্ডের মেসেজ রাখা হয় না। ৩০ দিন পর নিজে থেকে মুছে যায়।': 'Messages are stored encrypted on this phone only; they’re never sent to a server or the AI. OTP, PIN and password messages are never saved. They’re deleted after 30 days.',
