  'যা খুঁজবেন লিখুন — যেমন “রহিম”, “গাড়ির কাগজ”, “বিদ্যুৎ বিল”। মুখে জিজ্ঞেস করতে মাইক চাপুন।': 'Type what you’re looking for — e.g. “Rahim”, “car papers”, “electricity bill”. Tap the mic to search by voice.',
  'যা খুঁজবেন লিখুন — যেমন “রহিম”, “গাড়ির কাগজ”। নিচে সাথে সাথে মিলে যাওয়া জিনিস দেখাবে। কিছু রাখতে বা জিজ্ঞেস করতে লিখে পাঠান (➤) — যেমন “রহিমকে ৫০০ টাকা দিলাম”।': 'Type what you’re looking for — e.g. “Rahim”, “car papers”. Matches appear below instantly. To save or ask something, type it and send (➤) — e.g. “Gave Rahim 500 taka”.',
