  'মা-বাবা, স্বামী-স্ত্রী, সন্তান — তাঁদের ইমেইল দিয়ে যুক্ত করুন। তাঁরা যা অনুমতি দেবেন, শুধু তা-ই করতে পারবেন: কাজ, রিমাইন্ডার, নোট, লাইভ লোকেশন।': 'Parents, spouse, children — add them by email. You can only do what they allow: tasks, reminders, notes, live location.',
  'পাওনা ৩০ দিন পার, বিলের শেষ দিন পরশু, কাগজের মেয়াদ': 'Money owed for over 30 days, a bill due in two days, documents expiring',
  'স্বাস্থ্যে পরিবারের সদস্য যুক্ত করে প্রত্যেকের BMI, ওজন, হাঁটা আর ঘুম আলাদা রাখা': 'Add family members in Health and track each person’s BMI, weight, walking and sleep separately',
  'সদস্য যুক্ত করা, কাজ, রিমাইন্ডার আর নোট পাঠানো': 'Adding members; sending tasks, reminders and notes',
  'মুখে বলে সব কাজ, আয়-ব্যয়, এখন আছে, ধার-দেনা (যত জন খুশি) ও তার রিমাইন্ডার, তাগাদার মেসেজ, কাজের তালিকা, অ্যালার্ম, ক্যালেন্ডার ও নামাজের সময়, নোট, কাগজের মেয়াদের খবর, সব মাসের রিপোর্ট, নিজের স্বাস্থ্য, অভ্যাস, বিশেষ দিন, যাকাতের হিসাব, সঞ্চয়, দোকান ও রসিদ, স্মার্ট খেয়াল, ফ্যামিলিতে কাজ-রিমাইন্ডার-নোট পাঠানো, নিজে চাপলে Google Drive-এ ব্যাকআপ আর নতুন ফোনে সব ফিরিয়ে আনা। আপনার রাখা কোনো তথ্য কখনো তালাবদ্ধ হবে না।': 'Everything by voice, income and expenses, current balance, loans (any number of people) with reminders, payment reminder messages, to-dos, alarms, calendar and prayer times, notes, document expiry alerts, monthly reports, your own health, habits, special days, zakat, savings, shop and receipts, smart tips, sending tasks, reminders and notes in Family, manual Google Drive backup and restoring everything on a new phone. Nothing you save is ever locked.',
  'BMI, ওজন, পানি, হাঁটা আর ঘুম — গ্রাফসহ; BMI বেশি হলে উৎসাহের নোটিফিকেশন। পরিবারের সদস্য যুক্ত করা প্রিমিয়ামে।': 'BMI, weight, water, walking and sleep — with charts; an encouraging notification when your BMI is high. Adding family members is Premium.',
  'পরিবারের সদস্যদের ইমেইলে যুক্ত করে কাজ, রিমাইন্ডার, নোট পাঠানো। অ্যাপ ব্যবহারের সময় “এখন কোথায়?” চেপে লোকেশন; উত্তরাধিকারী এক চাপে সব ব্যাকআপ পান (লোকেশন আর উত্তরাধিকার প্রিমিয়ামে)।': 'Add family members by email and send them tasks, reminders and notes. Tap “Where now?” to see their location while they’re using the app; heirs get a full backup in one tap (location and inheritance are Premium).',
  'দিনের কথা লিখে রাখা; নিচে অভ্যাস, বিশেষ দিন আর তৈরি তালিকা।': 'Write about your day; below it are habits, special days and ready-made checklists.',
  'ওষুধ, প্রেশার, সুগার আর জরুরি কার্ড Google Play-র এই অ্যাপে নেই। সময়মতো কিছু মনে করাতে সাধারণ রিমাইন্ডার দিতে পারেন।': 'Medicines, blood pressure, blood sugar and the emergency card aren’t available in the Google Play version of this app. You can set an ordinary reminder for anything you need to remember on time.',
