  'আপনার তথ্য আপনার ফোনেই থাকে, PIN দিয়ে তালা দেওয়া। পাসওয়ার্ড, পিন আর ওটিপি কখনো ফোনের বাইরে যায় না। ব্যাকআপ যায় আপনার নিজের Google Drive-এ, তালা দেওয়া অবস্থায়। ফ্যামিলিতে কিছু পাঠালে শুধু সেই মানুষটাই খুলতে পারেন। কথা বুঝতে সাহায্য লাগলে শুধু সেই কথাটুকু আমাদের সার্ভারে যায়।': 'Your data stays on your phone, locked with your PIN. Passwords, PINs and OTPs never leave the phone. Backups go to your own Google Drive, encrypted. Anything you send in Family can only be opened by that person. When help is needed to understand something you said, only those words are sent to our server.',
  'শুধু এই ফোনে, অ্যাপের এনক্রিপ্ট করা ফাইলে। আমাদের সার্ভারে বা কারও কাছে যায় না।': 'Only on this phone, in the app’s encrypted file. It’s never sent to our server or anyone else.',
  'শুধু এই ফোনে, তালাবদ্ধ অবস্থায় থাকে। পুরো নম্বর আর ছবি দেখতে আঙুলের ছাপ বা PIN লাগে। আমাদের সার্ভারে কখনো যায় না। কার্ডের PIN বা পিছনের CVV কোথাও লিখে রাখবেন না।': 'Only on this phone, locked. Viewing the full number and photos requires your fingerprint or PIN. It’s never sent to our server. Never write down the card’s PIN or the CVV on the back.',
  'মুখে বললে কথাকে লেখায় রূপান্তর করে ফোনের নিজের ভয়েস সেবা (সাধারণত Google)। সেজন্য আপনার কণ্ঠ ইন্টারনেটে Google-এর কাছে যেতে পারে — আমাদের সার্ভারে নয়। না চাইলে লিখে ব্যবহার করুন।': 'When you speak, your phone’s own speech service (usually Google) converts it to text, so your voice may be sent over the internet to Google — not to our server. If you’d rather not, type instead.',
  'এখানে লেখা কথাগুলো সহকারী উত্তর দেওয়ার সময় মনে রাখে। মুখেও বলা যায়: “মনে রেখো, রহিম আমার শ্যালক”। উত্তর তৈরিতে এগুলো আমাদের সার্ভারে পাঠানো হয়; পাসওয়ার্ড বা গোপন কিছু এখানে লিখবেন না।': 'The assistant keeps these in mind when answering. You can also say: “Remember, Rahim is my brother-in-law.” These are sent to our server to generate answers; don’t write passwords or secrets here.',
  'পাসওয়ার্ড ও নম্বর ফোনেই থাকে · চালু থাকলে আপনার কথা আমাদের সার্ভারে যায়': 'Passwords and numbers stay on the phone · when on, what you say is sent to our server',
  'শুধু এই ফোনে, তালাবদ্ধ অবস্থায় থাকে। দেখতে আঙুলের ছাপ বা PIN লাগে। আমাদের সার্ভারে কখনো যায় না, জোরে পড়াও হয় না।': 'Only on this phone, locked. Viewing it requires your fingerprint or PIN. It’s never sent to our server and never read aloud.',
  'বিস্তারিত — ওয়েবসাইটে': 'Learn more on our website',
  'জরুরি কার্ডে থাকবে; মোবাইল নম্বর আর শেষ রক্তদানের তারিখসহ আমাদের সার্ভারেও থাকবে, যেন বিপদে সাহায্য করা যায়।': 'Shown on the emergency card, and stored on our server with your mobile number and last donation date so we can help in an emergency.',
  'রক্তের গ্রুপ {0} — নম্বর আর শেষ রক্তদান দিন': 'Blood group {0} — add your number and last donation date',
  'বিপদে সাহায্যের জন্য এগুলো আমাদের সার্ভারে থাকবে': 'Stored on our server so we can help in an emergency',
  'শেষ কবে রক্ত দিয়েছেন — তারিখ দিন, অথবা “মনে নেই” বেছে নিন': 'When did you last donate blood? Pick a date, or choose “Don’t remember”',
  'রক্তের গ্রুপ, মোবাইল নম্বর আর শেষ রক্তদানের তারিখ আমাদের সার্ভারে থাকবে — যেন বিপদে আমরা আপনাকে বা আপনার জন্য রক্ত খুঁজে সাহায্য করতে পারি। গ্রুপ মুছে দিলে সার্ভার থেকেও মুছে যায়।': 'Your blood group, mobile number and last donation date are stored on our server so that in an emergency we can help find blood for you, or ask you to donate. Removing your blood group also removes it from the server.',
  'শেষ কবে রক্ত দিয়েছেন? *': 'When did you last donate blood? *',
  'মনে নেই / কখনো দিইনি': 'Don’t remember / never',
  'কার ওপর ফরজ': 'Who must pay',
  'মুসলিম, প্রাপ্তবয়স্ক, সুস্থ মস্তিষ্কের মানুষ, যিনি নিসাব পরিমাণ সম্পদের পূর্ণ মালিক।': 'An adult Muslim of sound mind who fully owns wealth at or above the nisab.',
  'শুধু আপনার নিজের মালিকানার সম্পদ ধরুন। স্ত্রী, স্বামী বা সন্তানের নিজের সোনা-টাকা তাঁদের নিজের যাকাতের হিসাবে যাবে।': 'Count only what you own yourself. Gold or money belonging to your wife, husband or child counts toward their own zakat.',
  'নিসাব': 'Nisab',
  'সাড়ে ৫২ ভরি (তোলা) রুপা — প্রায় ৬১২.৩৬ গ্রাম, অথবা সাড়ে ৭ ভরি সোনা — প্রায় ৮৭.৪৮ গ্রাম। শুধু সোনা থাকলে (আর কোনো যাকাতযোগ্য সম্পদ না থাকলে) সোনার নিসাব। নগদ টাকা, রুপা, ব্যবসার মাল বা একাধিক রকম সম্পদ থাকলে সব মিলিয়ে রুপার নিসাব — এতে গরিবের উপকার বেশি (প্রখ্যাত আলেমদের পরামর্শ অনুসারে)।': '52.5 bhori (tola) of silver — about 612.36 g — or 7.5 bhori of gold — about 87.48 g. If you own only gold (and nothing else zakatable), the gold nisab applies. If you have cash, silver, trade goods or more than one kind of wealth, everything is added up against the silver nisab — which is better for the poor (as renowned scholars advise).',
  'অ্যাপ নিজে দেখে নেয়: শুধু সোনা থাকলে সাড়ে ৭ ভরি সোনার দাম, নইলে সাড়ে ৫২ ভরি রুপার দাম।': 'The app decides for you: 7.5 bhori of gold if you own only gold, otherwise 52.5 bhori of silver.',
  'এক বছর পূর্ণ হওয়া': 'A full lunar year',
  'নিসাব পরিমাণ সম্পদ চান্দ্র বছর (প্রায় ৩৫৪ দিন) মালিকানায় থাকলে যাকাত ফরজ। বছরের শুরু আর শেষে নিসাব থাকলেই হয় — মাঝে কমবেশি হলে ক্ষতি নেই। বছরের মাঝে যে টাকা এসেছে, শেষ দিনে তা-ও যোগ হয়। মাঝে সম্পদ পুরো শেষ হয়ে গেলে আবার নতুন করে বছর গোনা শুরু।': 'Zakat is due when wealth at or above the nisab stays in your ownership for a lunar year (about 354 days). It’s enough to have the nisab at the start and end of the year — ups and downs in between don’t matter. Money received during the year is added on the last day. If the wealth runs out completely in between, the year starts over.',
  'যেদিন প্রথম নিসাব পূর্ণ হয়েছিল সেই দিন দিন — অ্যাপ প্রতি চান্দ্র বছরে যাকাতের দিন মনে করিয়ে দেবে। হিসাবটা সেদিনের সম্পদ দিয়ে করুন।': 'Enter the day you first reached the nisab — the app will remind you of your zakat day every lunar year. Calculate using what you own on that day.',
  'হার': 'Rate',
  'দেনা বাদে মোট যাকাতযোগ্য সম্পদের ২.৫% — ৪০ ভাগের ১ ভাগ।': '2.5% — one-fortieth — of all zakatable wealth after debts.',
  'অ্যাপ ঠিক এভাবেই গোনে।': 'The app calculates exactly this way.',
  'যা ধরা হয়': 'What counts',
  'নগদ টাকা; ব্যাংক ও মোবাইল ব্যাংকিংয়ের টাকা; সঞ্চয়; DPS ও FDR-এ নিজের জমা মূল টাকা; সোনা ও রুপা — গয়না নিজে পরলেও (প্রখ্যাত আলেমদের পরামর্শ অনুসারে); বিক্রির উদ্দেশ্যে কেনা মাল, জমি বা ফ্ল্যাট — বিক্রয়মূল্যে; শেয়ার — বাজারমূল্যে; ফেরত পাওয়ার আশা আছে এমন পাওনা; হজ, বিয়ে বা অন্য কাজে জমানো টাকা; প্রভিডেন্ট ফান্ডে নিজের ইচ্ছায় জমানো অংশ; জমানো ভাড়ার টাকা।': 'Cash; money in bank and mobile banking accounts; savings; your own deposits in DPS and FDR; gold and silver — including jewelry you wear (as renowned scholars advise); goods, land or flats bought for resale — at selling price; shares — at market price; money owed to you that you expect to get back; money saved for Hajj, a wedding or anything else; your voluntary provident fund contributions; saved rent.',
  'অ্যাকাউন্ট, সঞ্চয়, DPS আর ধার-দেনা থেকে অ্যাপ নিজে নেয়; সোনা-রুপা, ব্যবসার মাল আর বাকি সব নিচের ঘরে বা “নিজে যোগ করুন” দিয়ে লিখুন।': 'The app takes accounts, savings, DPS and loans into account automatically; enter gold, silver, trade goods and anything else in the boxes below or with “Add your own”.',
  'যা ধরা হয় না': 'What does not count',
  'থাকার বাড়ি; নিজের ব্যবহারের গাড়ি, আসবাব, কাপড়, ফোন, সংসারের জিনিস; ভাড়া দেওয়া বাড়ি বা দোকানের নিজের দাম (ভাড়ার জমানো টাকা ধরা হয়); ব্যবসার যন্ত্রপাতি, দোকানের আসবাব; গয়নার পাথর আর মজুরি; যে পাওনা ফেরত পাওয়ার আশা নেই (হাতে এলে তখন ধরা হয়); বাধ্যতামূলক প্রভিডেন্ট ফান্ড — হাতে পাওয়ার আগে।': 'The home you live in; your own car, furniture, clothes, phone and household items; the value of a house or shop you rent out (saved rent does count); business tools and shop fittings; gemstones and making charges in jewelry; money owed to you that you don’t expect back (count it when it’s repaid); a compulsory provident fund — until you receive it.',
  'এগুলো অ্যাপ নিজে কখনো যোগ করে না। কোনো পাওনা ফেরত পাওয়ার আশা না থাকলে তার টিক তুলে দিন।': 'The app never adds these. If you don’t expect a loan to be repaid, untick it.',
  'দেনা বাদ যায়': 'Debts are deducted',
  'যে ঋণ শোধ করতে হবে তা সম্পদ থেকে বাদ যায়। দীর্ঘমেয়াদি কিস্তির ঋণে শুধু সামনের ১২ মাসের কিস্তি বাদ যায়, পুরো ঋণ নয়। বকেয়া বিল, ভাড়া আর আগের বছরের না দেওয়া যাকাতও দেনা।': 'Debts you must repay are deducted from your wealth. For a long-term installment loan, only the next 12 months of installments are deducted, not the whole loan. Unpaid bills, rent and zakat left unpaid from earlier years are debts too.',
  'ধার-দেনার দেনা আর লোনের সামনের ১২টা কিস্তি অ্যাপ নিজে বাদ দেয়। বকেয়া বিল বা আগের যাকাত “নিজে যোগ করুন” › দেনা দিয়ে লিখুন।': 'Money you owe people and the next 12 loan installments are deducted automatically. Enter unpaid bills or earlier zakat with “Add your own” › Debt.',
  'সুদ': 'Interest',
  'সুদের টাকা যাকাতযোগ্য সম্পদ নয়, নিজের সম্পদই নয়। পুরোটা সওয়াবের নিয়ত ছাড়া গরিবকে দিয়ে দিতে হয়।': 'Interest is not zakatable wealth — it isn’t yours at all. All of it must be given to the poor without expecting reward.',
  'ব্যাংক বা সঞ্চয়ের ব্যালেন্সে সুদ থাকলে “নিজে যোগ করুন” › দেনা দিয়ে সেই অঙ্ক লিখুন — হিসাব থেকে বাদ যাবে।': 'If a bank or savings balance includes interest, enter that amount with “Add your own” › Debt — it will be deducted.',
  'সোনা-রুপার দাম': 'Gold and silver prices',
  'যাকাতের দিনের বাজারদরে — এখন বিক্রি করলে যে দাম পাওয়া যাবে। গয়নার ক্যারেট অনুযায়ী দাম ধরতে হয়।': 'At the market price on your zakat day — what it would fetch if sold now — according to the jewelry’s carat.',
  'বাজুসের আজকের দাম আনা যায়। কয়েক ক্যারেটের সোনা থাকলে প্রতিটা আলাদা লিখুন — প্রতিটির দাম তার ক্যারেট অনুযায়ী; অন্য রকম সোনার দাম নিজে লিখুন। দোকানে বিক্রির দাম কম হলে নিজে দাম বদলে দিন।': 'You can fetch today’s BAJUS price. If you have gold of several carats, enter each separately at its own carat’s price; for other gold, enter the price yourself. If a shop would pay less, change the price yourself.',
  'একই টাকা দুবার নয়': 'No double counting',
  'যে টাকা একবার ধরা হয়েছে, তা আবার ধরা যাবে না।': 'Money already counted must not be counted again.',
  'সঞ্চয়ের লক্ষ্যের টাকা যদি কোনো অ্যাকাউন্টের ব্যালেন্সেই থাকে, দুটোর একটির টিক তুলে দিন।': 'If money in a savings goal is also part of an account’s balance, untick one of the two.',
  'অন্যের টাকা, আমানত': 'Other people’s money and trusts',
  'কমিটি, মসজিদ, সমিতি বা অন্যের রাখা টাকার যাকাত আপনার ওপর নয়। টাকাটা আপনার নিজের হলে অবশ্যই ধরতে হবে।': 'Zakat on money you hold for a committee, mosque, society or someone else isn’t your obligation. If the money is your own, it must be counted.',
  'মূল হিসাবে যুক্ত নয় এমন “অন্যান্য হিসাব” টিক না দিলে ধরা হয় না। নিজের টাকা হলে টিক দিন।': 'A Project that isn’t linked to your main finances is only counted if you tick it. Tick it if the money is yours.',
  'কাদের দেওয়া যায়': 'Who can receive zakat',
  'সূরা তাওবা ৬০: ফকির, মিসকিন, যাকাত আদায়ের কর্মী, যাদের মন ইসলামের দিকে আনতে হয়, দাসমুক্তি, ঋণগ্রস্ত, আল্লাহর পথে, অসহায় মুসাফির। গরিব ভাই-বোন, চাচা-ফুফু, মামা-খালা আর তাঁদের সন্তানদের দেওয়া যায় — বরং উত্তম।': 'At-Tawbah 9:60: the poor, the needy, zakat collectors, those whose hearts are to be reconciled, freeing captives, those in debt, in the cause of Allah, and stranded travelers. Poor brothers and sisters, uncles, aunts and their children may receive it — it’s even better.',
  'কাদের দেওয়া যায় না': 'Who cannot receive zakat',
  'নিজের বাবা-মা, দাদা-দাদি, নানা-নানি; নিজের সন্তান, নাতি-নাতনি; স্বামী বা স্ত্রী; নিসাবের মালিক সচ্ছল মানুষ; অমুসলিম (প্রখ্যাত আলেমদের পরামর্শ অনুসারে); নবী (সা.)-এর বংশধর (বনু হাশিম)।': 'Your own parents and grandparents; your own children and grandchildren; your husband or wife; well-off people who own the nisab; non-Muslims (as renowned scholars advise); descendants of the Prophet (ﷺ) (Banu Hashim).',
  'মালিক বানিয়ে দেওয়া': 'Transfer ownership',
  'যাকাত গরিবকে মালিক বানিয়ে দিতে হয়। মসজিদ বানানো, রাস্তা, মৃতের কাফন-দাফনে সরাসরি খরচ করলে যাকাত আদায় হয় না। দেওয়ার সময় (বা আলাদা করে রাখার সময়) মনে মনে যাকাতের নিয়ত লাগবে; “যাকাত” বলে দিতে হয় না।': 'Zakat must be handed over into a poor person’s ownership. Spending it directly on building a mosque, roads or a funeral doesn’t fulfill it. Make the intention of zakat in your heart when giving (or setting it aside); you don’t need to call it zakat.',
  'আগে দেওয়া যায়': 'Paying in advance',
  'নিসাবের মালিক হলে বছর শেষ হওয়ার আগেই অগ্রিম যাকাত দেওয়া যায়; বছর শেষে হিসাব মিলিয়ে বাকিটা দিন।': 'If you own the nisab, you may pay zakat before the year ends; settle the rest at the end of the year.',
  ' শুধু সোনা আছে, অন্য কোনো যাকাতযোগ্য সম্পদ নেই — তাই নিসাব সাড়ে ৭ ভরি সোনা।': ' You own only gold and nothing else zakatable — so the nisab is 7.5 bhori of gold.',
  'আলাদা রাখা হিসাব — টাকা আপনার নিজের হলে টিক দিন': 'Separate Projects — tick if the money is yours',
  'হাতে {0}': 'On hand {0}',
  'বকেয়া পাবেন {0}': 'Dues owed to you {0}',
  'বকেয়া দেবেন {0}': 'Dues you owe {0}',
  'যাকাতের মূলনীতি': 'Principles of zakat',
  'এই অ্যাপের যাকাতের হিসাব নিচের মূলনীতি মেনে করা — প্রখ্যাত আলেমদের পরামর্শ অনুসারে। প্রতিটির নিচে লেখা আছে অ্যাপ সেটা কীভাবে মানে।': 'This app calculates zakat according to the principles below, following the advice of renowned Islamic scholars. Under each one is how the app applies it.',
  'এটা প্রচলিত মত অনুযায়ী হিসাব। নিজের অবস্থা অনুযায়ী নিশ্চিত হতে একজন আলেম বা মুফতির পরামর্শ নিন।': 'This follows the widely held view. For your own situation, consult a scholar or mufti.',
  '{0}, {1} থেকে কার্যকর — আপনার বেছে নেওয়া ক্যারেটের দাম বসানো হলো। দোকানে বিক্রির দাম কম হলে নিজে বদলে দিন।': '{0}, effective {1} — the price for your chosen carat has been filled in. If a shop would pay less, change it yourself.',
  'নিসাব জানতে নিচে আজকের সোনার দাম দিন': 'Enter today’s gold price below to see the nisab',
  'নিসাব (সাড়ে ৭ ভরি সোনা — শুধু সোনা আছে বলে): {0}': 'Nisab (7.5 bhori of gold — since you own only gold): {0}',
  'নিসাব (সাড়ে ৫২ ভরি রুপা): {0}': 'Nisab (52.5 bhori of silver): {0}',
  'নিসাব, বছর, কী ধরা হয়, কী হয় না, দেনা, সুদ, কাদের দেওয়া যায় — আর এই হিসাব কীভাবে মানে': 'Nisab, the lunar year, what counts and what doesn’t, debts, interest, who can receive it — and how this calculation applies them',
  'এই টাকা কোনো অ্যাকাউন্টের ব্যালেন্সেই থাকলে একটির টিক তুলে দিন — একই টাকা দুবার ধরা যায় না।': 'If this money is also part of an account’s balance, untick one — the same money can’t be counted twice.',
  'আপনার সোনার গয়না কত ক্যারেটের?': 'What carat is your gold jewelry?',
  'কথা বোঝা আরও ভালো করতে আমরা প্রতিনিয়ত কাজ করছি — কোনো কথা ভুল বুঝলে আরেকভাবে বলুন বা লিখে দিন।': 'We’re always working to understand you better — if something is misheard, say it another way or type it.',
