  'Google দিয়ে লগইন করলে, বা ফোনে রাখা ব্যাকআপ ফাইল বেছে নিলে, আগের সব তথ্য ফিরে আসবে': 'Sign in with Google, or choose a backup file saved on this phone, to restore everything',
