  'চালু থাকলে অ্যাপ থেকে বের হলে নতুন লগ আমাদের কাছে যায়, যাতে সমস্যা খুঁজে ঠিক করতে পারি। নম্বর লুকানো থাকে; পাসওয়ার্ড, ভল্ট, PIN/OTP, স্বাস্থ্য, ওষুধ বা মেসেজ নিয়ে যে কথোপকথন — সেটা পুরোটাই বাদ যায়, ফোনের বাইরে যায় না।': 'When on, the new log is sent to us each time you leave the app, so we can find and fix problems. Numbers are hidden; any conversation about passwords, the vault, PIN/OTP, health, medicines or messages is left out entirely and never leaves the phone.',
