  'তারিখটা ধরতে পারিনি। যেমন বলুন “৩১ অক্টোবর” বা “শুক্রবার”।': 'I didn’t catch the date. Say, for example, “31 October” or “Friday”.',
  'ঠিক আছে, অঙ্কটা বদলে দিলাম। এখন এভাবে রেখে দিই?': 'Done, I changed the amount. Save it like this?',
  '{0} নম্বর': 'number {0}',
  '{0}ঠিক অঙ্কটা বলুন, যেমন “{1} ৩০০ টাকা”। ঠিক হলে তারপর রাখব — এখনো কিছু রাখিনি।': '{0}tell me the correct amount, e.g. “{1} 300 taka”. I’ll save it once it’s right — nothing has been saved yet.',
  '{0}টা কাজের রিমাইন্ডার — প্রতিটা নিজের দিনে, কয়টায় মনে করাব? যেমন “দুপুর ১২টায়”।': 'Reminders for {0} to-dos — each on its own day. What time? E.g. “12 noon”.',
  '“{0}” — কোন তারিখে রাখব? যেমন “৩১ অক্টোবর”।': '“{0}” — which date? E.g. “31 October”.',
  ' আজকের দাম ইন্টারনেট থেকে আনতে পারিনি (ইন্টারনেট বা সার্ভার সাড়া দেয়নি) — বাজুসের সাইটে (bajus.org) দেখে নিতে পারেন।': ' I couldn’t get today’s price (no internet, or the server didn’t respond) — you can check it on bajus.org.',
  'বুঝেছি — কাজগুলো আলাদা আলাদা হবে। আগের কথাটা আবার বলুন, শুরুতে দিন আর “কাজ”, তারপর কমা দিয়ে একেকটা কাজ — যেমন “১০ জানুয়ারি কাজ গুলো, রবিনকে কল করব, নাস্তা করব, মসজিদে যাবো”। প্রতিটা আলাদা কাজ হিসেবে রাখব।': 'Got it — they should be separate to-dos. Say it again with the day and “to-dos” first, then each to-do separated by a comma — e.g. “10 January to-dos, call Robin, have breakfast, go to the mosque”. Each will be saved separately.',
