  'রক্ত চাইতে, দাতা হতে বা অনুরোধ দেখতে আগে Google দিয়ে লগইন করুন।': 'Sign in with Google first to request blood, become a donor or view requests.',
  'সারা দেশের অনুরোধ': 'Requests nationwide',
  'গ্রুপ': 'Blood group',
  'সব গ্রুপ': 'All blood groups',
  'সারা দেশ': 'Nationwide',
  'রক্ত দরকার হলে নিচের “রক্ত চাই” চাপুন — সারা দেশের সবাই দেখবেন, আর আপনার জেলার দাতারা সাথে সাথে জানবেন।': 'If you need blood, tap “Need blood” below — everyone in the country will see it, and donors in your district are notified immediately.',
  'দেশের যেকোনো জায়গায় কারো রক্ত লাগলে এখানে দেখাবে; দাতা হলে নিজের জেলার অনুরোধে নোটিফিকেশনও পাবেন।': 'Blood requests from anywhere in the country appear here; as a donor, you’ll also be notified of requests in your district.',
