  'রোগীর সমস্যা': 'Patient’s condition',
  'যেমন: সিজারিয়ান অপারেশন, থ্যালাসেমিয়া, দুর্ঘটনা': 'e.g. C-section, thalassemia, accident',
  'হাসপাতাল': 'Hospital',
  'হাসপাতালের অবস্থান (এলাকা, ঠিকানা, ওয়ার্ড)': 'Hospital location (area, address, ward)',
  'যেমন: বকশিবাজার, ওয়ার্ড ৩': 'e.g. Bakshibazar, Ward 3',
  'আর কিছু বলার থাকলে (ঐচ্ছিক)': 'Additional details (optional)',
  'যেমন: সকাল ১০টার আগে আসুন': 'e.g. Please come before 10 am',
  'অনুরোধটা সারা দেশের সবাই দেখবেন — কার জন্যে, সমস্যা, হাসপাতাল, তারিখ আর আপনার নম্বরসহ। আপনার জেলার যাঁরা দাতা আর এই গ্রুপে দিতে পারেন, তাঁরা নোটিফিকেশনও পাবেন। একসাথে ৩টা পর্যন্ত অনুরোধ খোলা রাখা যায়।': 'Everyone in the country will see this request — the patient, their condition, the hospital, the date and your number. Donors in your district with a matching blood group are also notified. You can have up to 3 open requests at a time.',
  'অনুরোধ পাঠানো হয়েছে — তিনি অ্যাপে মেনে নিলে যুক্ত হবেন': 'Request sent — they’ll join once they accept in the app',
  'সদস্য যোগ': 'Add member',
  'ফ্যামিলিতে যুক্ত হতে আগে Google দিয়ে লগইন করুন — সবাই নিজের ইমেইলে যুক্ত হন।': 'Sign in with Google first to use Family — each member joins with their own email.',
  '{0} জানিয়েছেন আপনি ইন্তেকাল করেছেন': '{0} has reported that you have passed away',
  'ভুল হলে এখনই বাতিল করুন। বাতিল না করলে যাচাইয়ের পর ১৪ দিনে তিনি আপনার বেছে রাখা অংশ দেখতে পাবেন।': 'If this is wrong, cancel it now. Otherwise, after verification and 14 days, they’ll be able to see the items you chose.',
  'আমি বেঁচে আছি — বাতিল করুন': 'I’m alive — cancel this',
  'ফ্যামিলি থেকে এসেছে': 'Received from family',
  'যুক্ত হওয়ার অনুরোধ': 'Join requests',
  '{0} আপনাকে ফ্যামিলিতে যুক্ত করতে চান': '{0} wants to add you to their family',
  'তিনি আপনাকে বলেছেন: {0}': 'They call you: {0}',
  'যুক্ত হোন': 'Join',
  'আমার ফ্যামিলি': 'My family',
  'এখনো কেউ নেই': 'No one yet',
  'মা-বাবা, স্বামী-স্ত্রী, সন্তান — তাঁদের ইমেইল দিয়ে যুক্ত করুন। তাঁরা যা অনুমতি দেবেন, শুধু তা-ই করতে পারবেন: কাজ, রিমাইন্ডার, ওষুধের রিমাইন্ডার, নোট, লাইভ লোকেশন।': 'Parents, spouse, children — add them by email. You can only do what they allow: to-dos, reminders, medicine reminders, notes, live location.',
  'আপনাকে এখনো কিছুর অনুমতি দেননি': 'Hasn’t given you any permissions yet',
  'অনুমতি: {0}': 'Allowed: {0}',
  'উত্তরের অপেক্ষায় — তিনি অ্যাপ খুলে মেনে নেবেন': 'Pending — they’ll accept when they open the app',
  'আমার লোকেশন': 'My location',
  'লোকেশন দেখাতে ফোনের অনুমতি লাগবে।': 'Showing your location requires the phone’s location permission.',
  'অ্যাপ খোলা থাকলে লোকেশন যায়। ফোন হারালেও খুঁজে পেতে “সবসময়” অনুমতি দিন।': 'Your location is shared while the app is open. To also find a lost phone, choose “Allow all the time”.',
  'চালু — অ্যাপ বন্ধ থাকলেও “এখন কোথায়?” জিজ্ঞেস করলে ফোন নিজে জানাবে।': 'On — even when the app is closed, your phone answers “Where now?” automatically.',
  'লোকেশনের অনুমতি দিন': 'Allow location',
  '“সবসময় অনুমতি দিন” বেছে নিন': 'Choose “Allow all the time”',
  'My Assistant আপনার ফোনের লোকেশন নেয় শুধু তখন, যখন অ্যাপ ব্যবহারের সময় আপনি যাঁদের অনুমতি দিয়েছেন সেই পরিবারের কেউ “এখন কোথায়?” জিজ্ঞেস করেন। লোকেশন তালাবদ্ধ হয়ে শুধু তাঁদের কাছে যায়; আমরা দেখতে পারি না, বিজ্ঞাপনে বা অন্য কিছুতে ব্যবহার হয় না। ফ্যামিলি পাতা থেকে যেকোনো সময় বন্ধ করা যায়।': 'My Assistant accesses your phone’s location only when a family member you’ve approved asks “Where now?” while the app is in use. Your location is encrypted so only they can open it; we can’t see it, and it’s never used for ads or anything else. You can turn this off on the Family page at any time.',
  'চালু — অ্যাপ ব্যবহারের সময় “এখন কোথায়?” জিজ্ঞেস করলে লোকেশন যায়।': 'On — when someone asks “Where now?” while the app is in use, your location is shared.',
  'লোকেশন তালাবদ্ধ হয়ে যায় — শুধু যাঁদের অনুমতি দিয়েছেন তাঁরাই খুলতে পারেন, আমাদের সার্ভারও না।': 'Your location is encrypted — only the people you’ve allowed can open it; not even our server can.',
  'উত্তরাধিকারী': 'Heirs',
  'কোনো সদস্যকে খুলে “আমার উত্তরাধিকারী” চালু করলে, আপনার ইন্তেকালের পর (কাগজ যাচাই আর ১৪ দিন অপেক্ষার পর) বা আপনি এখনই অনুমতি দিলে তিনি নিচে বাছাই করা অংশ দেখতে পাবেন।': 'Open a member and turn on “My heir”: after your death (document verification plus 14 days), or immediately if you allow it, they can see the items chosen below.',
