  'ইন্তেকালের খবর দিন': 'Report a death',
  'মৃত্যু সনদের ছবি লাগবে। আমরা যাচাই করব, তাঁর ফোন আর ইমেইলে জানাব; ১৪ দিনের মধ্যে কেউ বাতিল না করলে তিনি যা বেছে রেখেছেন, আপনি দেখতে পাবেন।': 'A photo of the death certificate is required. We’ll verify it and notify their phone and email; if no one cancels within 14 days, you’ll see what they chose to share.',
