  'আমার ইন্তেকালের পর (কাগজ যাচাই আর ১৪ দিন পর) ফ্যামিলি পাতায় বাছাই করা অংশ দেখবেন': 'After my death (document verification plus 14 days), they can see the chosen items on the Family page',
