  'তারিখ দিন': 'Set date',
  'যাকাত কী, কার ওপর, কীভাবে হিসাব': 'What zakat is, who must pay and how it’s calculated',
  '• নিসাব: সাড়ে ৫২ ভরি রুপা (বা সাড়ে ৭ ভরি সোনা) সমান সম্পদ এক চান্দ্র বছর ধরে থাকলে যাকাত ফরজ।\n• হার: যাকাতযোগ্য সম্পদের ২.৫% (৪০ ভাগের ১ ভাগ)।\n• ধরা হয়: নগদ, ব্যাংক ও মোবাইল ব্যাংকিংয়ের টাকা, সঞ্চয়, DPS-এ জমা, সোনা-রুপা, ব্যবসার মাল, ফেরত পাওয়ার আশা আছে এমন পাওনা।\n• ধরা হয় না: থাকার বাড়ি, নিজের ব্যবহারের গাড়ি-আসবাব, সংসারের জিনিস।\n• বাদ যায়: যে দেনা শোধ করতে হবে।\n• কাদের দেওয়া যায়: গরিব, মিসকিন, ঋণগ্রস্ত, মুসাফির ইত্যাদি (সূরা তাওবা ৬০)।\nএটা আনুমানিক হিসাব — নিশ্চিত হতে আলেমের পরামর্শ নিন।': '• Nisab: zakat is due when you hold wealth equal to 52.5 bhori of silver (or 7.5 bhori of gold) for a lunar year.\n• Rate: 2.5% (one-fortieth) of zakatable wealth.\n• Included: cash, money in bank and mobile banking accounts, savings, DPS deposits, gold and silver, business inventory, money owed to you that you expect back.\n• Not included: the home you live in, your own car and furniture, household items.\n• Deducted: debts you must repay.\n• Who can receive it: the poor, the needy, people in debt, travelers and others (Surah At-Tawbah 9:60).\nThis is an estimate — consult a scholar to be sure.',
  'হিসাব কোথা থেকে এল': 'Where these figures come from',
  'আয়-ব্যয়, অ্যাকাউন্ট, সঞ্চয়, কিস্তি আর ধার-দেনা থেকে নিজে আসে; সেখানে বদলালে এখানেও বদলায়। টিক তুলে দিলে সেটা বাদ যাবে, চাপলে কোন লেনদেন থেকে এল দেখাবে।': 'Pulled automatically from Income & Expenses, Accounts, Savings, Installments and Loans; change them there and it updates here. Untick a line to exclude it; tap it to see the transactions behind it.',
  'এখনো কিছু নেই — অ্যাকাউন্ট, ধার-দেনা বা নিচে সোনা-রুপা লিখলে এখানে আসবে।': 'Nothing yet — add accounts, loans, or gold and silver below and they’ll appear here.',
  'নিজে কিছু যোগ করুন': 'Add your own',
  'মুখেও জিজ্ঞেস করা যায়: “আমার যাকাত কত?” — এই পাতার একই হিসাব থেকে উত্তর আসে।': 'You can also ask by voice: “How much is my zakat?” — the answer uses this same calculation.',
  'রক্ত দরকার হলে অনুরোধ দিন — কার জন্যে, সমস্যা, হাসপাতাল, তারিখ আর নম্বরসহ; সারা দেশের সবাই দেখবেন, আপনার জেলার দাতারা নোটিফিকেশনও পাবেন। দাতা হলে “আমি দিতে পারব” বলতে পারবেন।': 'Request blood with the patient, their condition, the hospital, the date and a phone number; everyone in the country sees it, and donors in your district are notified. As a donor, you can respond with “I can donate”.',
  'ব্লাড ডোনেশন খোলো': 'Open Blood donation',
  'পরিবারের সদস্যদের ইমেইলে যুক্ত করে তাঁদের জন্য কাজ, রিমাইন্ডার, ওষুধের রিমাইন্ডার, নোট দেওয়া; অনুমতি থাকলে লাইভ লোকেশন; উত্তরাধিকারী (প্রিমিয়াম)।': 'Add family members by email and send them to-dos, reminders, medicine reminders and notes; see their live location if they allow it; heirs (Premium).',
  'ফ্যামিলি খোলো': 'Open Family',
  'পরিবারের কারো জন্য কথায় কাজ বা রিমাইন্ডার পাঠানো': 'Sending a to-do or reminder to a family member by voice',
  'লোকেশন কীভাবে ব্যবহার হয়': 'How location is used',
  'My Assistant আপনার ফোনের লোকেশন নেয় — অ্যাপ বন্ধ থাকলেও — শুধু তখন, যখন আপনি যাঁদের অনুমতি দিয়েছেন সেই পরিবারের কেউ “এখন কোথায়?” জিজ্ঞেস করেন (যেমন ফোন হারালে খুঁজতে)। লোকেশন তালাবদ্ধ হয়ে শুধু তাঁদের কাছে যায়; আমরা দেখতে পারি না, বিজ্ঞাপনে বা অন্য কিছুতে ব্যবহার হয় না। ফ্যামিলি পাতা থেকে যেকোনো সময় বন্ধ করা যায়।': 'My Assistant accesses your phone’s location — even when the app is closed — only when a family member you’ve allowed asks “Where now?” (for example, to find a lost phone). It’s encrypted and goes only to them; we can’t see it, and it’s never used for ads or anything else. You can turn this off on the Family page at any time.',
