  'ধার-দেনার মতোই: কেউ বাকিতে নিলে বা আপনি বাকিতে নিলে লিখুন — কে, কী, কত টাকা, কবে শোধ। সেদিন মনে করিয়ে দেবো।': 'Just like loans: when someone buys on credit from you, or you buy on credit, record it here — who, what, how much and when it’s due. I’ll remind you on the day.',
  'প্রিমিয়াম চালু হয়েছে': 'Premium is active',
  'রিমাইন্ডার, ব্যাকআপ, ফ্যামিলি — সব প্রিমিয়াম সুবিধা এখন চালু। ধন্যবাদ!': 'Reminders, backup, Family — all Premium features are now active. Thank you!',
  'ফ্রি': 'Free',
  'ট্রায়াল': 'Trial',
  'শেষ কবে রক্ত দিয়েছেন জানা নেই। বলুন, যেমন “শেষ রক্ত দিয়েছি ১০ আগস্ট” — তিন মাস পরের দিনটা বলে দেবো।': 'I don’t know when you last donated blood. Say, for example, “I last donated blood on 10 August” — I’ll tell you the date three months later.',
  'শেষ দিয়েছেন {0}। আবার দিতে পারবেন {1} থেকে ({2})।': 'Last donated {0}. You can donate again from {1} ({2}).',
  'শেষ দিয়েছেন {0} — তিন মাস পেরিয়েছে, এখন দিতে পারবেন।': 'Last donated {0} — it’s been three months, so you can donate now.',
  'রেখে দিলাম — শেষ রক্ত দিয়েছেন {0}। আবার দিতে পারবেন {1} থেকে।': 'Saved — you last donated blood on {0}. You can donate again from {1}.',
  '[শেষ রক্তদানের দিন রাখা হলো]': '[Last blood donation date saved]',
  '{0} আয় {1} টাকা, খরচ {2} টাকা — {3} {4} টাকা।': '{0}: income ৳{1}, expenses ৳{2} — {3} ৳{4}.',
  'আয়ের চেয়ে বেশি খরচ': 'spent more than earned',
  'আপনার তথ্য আপনার ফোনেই থাকে, PIN দিয়ে তালা দেওয়া। পাসওয়ার্ড, পিন আর ওটিপি কখনো ফোনের বাইরে যায় না। ব্যাকআপ যায় আপনার নিজের Google Drive-এ, তালা দেওয়া অবস্থায়। ফ্যামিলিতে কিছু পাঠালে শুধু সেই মানুষটাই খুলতে পারেন। AI চালু থাকলে শুধু যে কথাটা বুঝতে সাহায্য লাগে সেটুকু যায়।': 'Your data stays on your phone, locked with your PIN. Passwords, PINs and OTPs never leave the phone. Backups go to your own Google Drive, encrypted. Anything sent in Family can only be opened by that person. With AI on, only the sentence that needs help understanding is sent.',
  '{0} কোনো কাজ, রিমাইন্ডার বা বিশেষ দিন রাখা নেই।': 'No tasks, reminders or special days {0}.',
