  'কোন হিসাবে বকেয়া?': 'Which project are the dues in?',
  'বাড়ি বানানো, দোকান, অফিসের কাজ, কোনো অর্ডার — প্রতিটার আলাদা আয়-ব্যয় আর বকেয়া রাখুন। কত এলো, কত গেল, কে কত বাকি দেখবেন।': 'Building a house, a shop, office work, an order — track separate income, expenses and dues for each. See what came in, what went out and who owes what.',
