  '“এখন আছে” কত টাকা আর কীভাবে হলো; নিজের আয় আর খরচ খাত ধরে; ধার আর অন্যান্য হিসাবের টাকা নিজে যুক্ত হয়।': 'Your current balance and how it was calculated; your own income and expenses by category; loans and Projects are linked automatically.',
  'কে কত পাবে, কাকে কত দিতে হবে, বকেয়াসহ; ফেরতের তারিখে মনে করায়; এক চাপে তাগাদার মেসেজ।': 'Who owes what, including dues; a reminder on the repayment date; a payment reminder message in one tap.',
  'প্রতিটা কাজের (বাড়ি, বিয়ে, ব্যবসা) আলাদা খরচ, বকেয়া আর বাজেট; টাকা মূল হিসাবে নিজে যুক্ত হয় (প্রিমিয়াম)।': 'Separate expenses, dues and budget for each project (house, wedding, business); automatically linked to your main balance (Premium).',
  '“এখন আছে”, ধার-দেনা, বকেয়া, সঞ্চয় আর সোনা-রুপা ধরে যাকাতের হিসাব; আজকের ভরির দাম নিজে আনে।': 'Zakat calculated from your current balance, loans, dues, savings, gold and silver; today’s price per bhori is fetched automatically.',
  'দোকানের নাম, নম্বর, ঠিকানা; বিক্রি, খরচ, কাস্টমারের বাকি আর রসিদ।': 'Shop name, phone number, address; sales, costs, customer dues and receipts.',
  'যা যা চান বেছে নিয়ে এক PDF-এ — ডাউনলোড, শেয়ার বা প্রিন্ট (প্রিমিয়াম)।': 'Choose what you want in one PDF — download, share or print (Premium).',
  'BMI, প্রেশার, সুগার, ওজন — গ্রাফসহ; BMI বেশি হলে উৎসাহের নোটিফিকেশন; শিশুর টিকার কার্ড; ডাক্তারকে দেখানোর সারাংশ। পরিবারের সদস্য যুক্ত করা প্রিমিয়ামে।': 'BMI, blood pressure, blood sugar, weight — with charts; an encouraging notification when your BMI is high; child vaccine card; a summary for your doctor. Adding family members is Premium.',
  'দিনের কথা লিখে রাখা; নিচে অভ্যাস, ওষুধ, বিশেষ দিন আর তৈরি তালিকা।': 'Write about your day; habits, medicines, special days and ready-made checklists below.',
  'যা মনে রাখতে চান; বিভাগ ধরে সাজানো, ছবি-ফাইল যোগ করা যায়, টিক-চিহ্নের তালিকাও। উপরে ওছিয়তনামা।': 'Anything you want to remember, organized by category, with photos and files, or as a checklist. Your will is at the top.',
  'NID, পাসপোর্ট, জমির কাগজ, প্রেসক্রিপশন, ওয়ারেন্টি, পরিবারের ছবি — নিজের নামের ফোল্ডারে, তালাবদ্ধ; অন্য কিছুর জন্য নতুন ফোল্ডার। প্রতিটার নাম বা ট্যাগ দিতে হয়, পরে বলে খোঁজা যায়।': 'NID, passport, land documents, prescriptions, warranties, family photos — each in its own encrypted folder; create a new folder for anything else. Each needs a name or a tag so you can find it by asking.',
  'Facebook, WhatsApp, Gmail, বিকাশ — এক চাপে নাম বসে; Wi-Fi, ব্যাংকের লগইন; দেখতে আঙুলের ছাপ বা PIN লাগে, কখনো জোরে পড়া হয় না।': 'Facebook, WhatsApp, Gmail, bKash — add the name in one tap; Wi-Fi and bank logins; fingerprint or PIN to view, never read aloud.',
  'রক্ত দরকার হলে অনুরোধ দিন — কার জন্যে, সমস্যা, হাসপাতাল, তারিখ আর নম্বরসহ; আপনার জেলার যাঁদের গ্রুপ মেলে, তাঁরা নোটিফিকেশন পান। মোবাইল নম্বর দিয়ে নিজেও দাতা হতে পারেন।': 'Request blood — patient, condition, hospital, date and phone number; donors in your district with a matching blood group are notified. Register as a donor with your mobile number.',
  'পরিবারের সদস্যদের ইমেইলে যুক্ত করে কাজ, রিমাইন্ডার, ওষুধের রিমাইন্ডার, নোট পাঠানো। ফোন হারালে “এখন কোথায়?” চেপে লোকেশন; উত্তরাধিকারী এক চাপে সব ব্যাকআপ পান (লোকেশন আর উত্তরাধিকার প্রিমিয়ামে)।': 'Add family members by email and send tasks, reminders, medicine reminders and notes. Lost phone? Tap “Where now?” to see its location; an heir can download a full backup in one tap (location and heirs are Premium).',
  'নাম, জেলা (ফোনের লোকেশন অনুযায়ী), রক্তের গ্রুপ, রক্তদান, ভাষা, থিম ও নিজের রং, সহজ মোড, তালা, ব্যাকআপ, মতামত পাঠানো।': 'Name, district (from your phone’s location), blood group, blood donation, language, theme and accent color, Simple mode, app lock, backup, feedback.',
  'সব তথ্য তালাবদ্ধ হয়ে নিজের Google Drive-এ বা ফাইলে; ফোন হারালে বা বদলালে নতুন ফোনে সব ফিরে আসে।': 'Everything encrypted in your own Google Drive or a file; if you lose or change your phone, it’s all restored on the new one.',
  'যত খুশি রিমাইন্ডার, ডকুমেন্ট আর পাসওয়ার্ড; অন্যান্য হিসাব, ওছিয়তনামা, পরিবারের স্বাস্থ্য, উত্তরাধিকার ও লোকেশন, অটো ব্যাকআপ, PDF, AI উত্তর — বিজ্ঞাপন ছাড়া। পেমেন্ট বিকাশে।': 'Unlimited reminders, documents and passwords; Projects, will, family health, heirs and location, automatic backup, PDF, AI answers — no ads. Pay with bKash.',
  'পাসপোর্ট, লাইসেন্স, ট্যাক্স টোকেনের মেয়াদ শেষের আগে মনে করায় (২০টা রিমাইন্ডারের মধ্যে ধরা)।': 'Reminds you before a passport, license or tax token expires (counts toward the 20 reminders).',
  'নিজের ওছিয়ত লিখে রাখা, কবে শেষ বদলেছেন তারিখসহ; উত্তরাধিকারী পরে দেখতে পান (প্রিমিয়াম)।': 'Write your will, with the date it was last changed; your heir can see it later (Premium).',
