  'দুঃখিত, ভুল বুঝেছিলাম। মুছে দিলাম — {0}।': 'Sorry, I misunderstood. Removed — {0}.',
  'ঠিক আছে, মুছিনি — যেমন ছিল তেমনই আছে।': 'OK, I didn’t remove it — it’s unchanged.',
  '“{0}”-এর জায়গায় কী হবে? শুধু সেটুকু বলুন — যেমন “তুবাকে”।': 'What should replace “{0}”? Say just that — like “Tuba”.',
  'দুঃখিত, আপনাকে বিরক্ত করে ফেলেছি।': 'Sorry for the trouble.',
  'দুঃখিত, দেরি করে ফেলেছি।': 'Sorry for the delay.',
  'বুঝতে পারছি, আপনি বিরক্ত — আমি দুঃখিত। এক লাইনে বলুন কী চান, আমি সেটাই করব। চাইলে কিবোর্ডে লিখেও দিতে পারেন।': 'I can tell you’re frustrated — I’m sorry. Tell me in one line what you’d like and I’ll do just that. You can also type it.',
  'এখন আছে {0}। কী বদলাব, শুধু সেটুকু বলুন।': 'Currently: {0}. Say only what to change.',
  'কী করব, ছোট করে বলুন।': 'Tell me briefly what to do.',
  'এখন রাখা আছে — {0}। ভুল হলে বলুন “এটা রাখতে বলিনি”, বা কোন শব্দ বদলাব — যেমন “X না, Y”।': 'Currently saved — {0}. If it’s wrong, say “I didn’t ask for this”, or which word to change — like “not X, Y”.',
  'এবার মন দিয়ে শুনছি — কী করব, আরেকবার বলুন; সময় থাকলে সময়সহ।': 'I’m listening — tell me once more what to do, with the time if there is one.',
  '“{0}” {1}-এ আগে থেকেই রাখা আছে — কিছু বদলাতে হয়নি।': '“{0}” is already set for {1} — nothing to change.',
  'ঠিক আছে — “{0}” এভাবেই রাখা আছে।': 'OK — “{0}” is already saved like that.',
  'দুঃখিত, আগেরবার ঠিক ধরতে পারিনি।': 'Sorry, I didn’t catch that the first time.',
  // অতিরিক্ত তালা (27 Oct)
  'অতিরিক্ত তালা খুলবেন?': 'Remove the extra lock?',
  'এরপর শুধু Google অ্যাকাউন্ট দিয়েই ব্যাকআপ খোলা যাবে। এখনই নতুন ব্যাকআপ নেওয়া হবে।': 'After this, your Google account alone can open the backup. A new backup will be made now.',
  'অতিরিক্ত তালা খুলতে যাচাই করুন': 'Verify it’s you to remove the extra lock',
  'অতিরিক্ত তালা': 'Extra lock',
  'ব্যাকআপে আপনার নিজের একটা পাসওয়ার্ডও লাগবে। কেউ আপনার Google অ্যাকাউন্ট দখল করলেও এই পাসওয়ার্ড ছাড়া ব্যাকআপ খুলতে পারবে না।\n\nসাবধান: পাসওয়ার্ড ভুলে গেলে নতুন ফোনে ব্যাকআপ আর খোলা যাবে না — কেউ উদ্ধার করতে পারবে না। কোথাও লিখে রাখুন।': 'The backup will also need a password of your own. Even someone who takes over your Google account can’t open it without this password.\n\nCaution: if you forget it, the backup can’t be opened on a new phone — no one can recover it. Write it down somewhere safe.',
  'পাসওয়ার্ড ঠিক করুন': 'Set password',
  'অতিরিক্ত তালা চালু — নতুন ব্যাকআপ নেওয়া হয়েছে।': 'Extra lock on — a new backup has been made.',
  'অতিরিক্ত তালা (নিজের পাসওয়ার্ড)': 'Extra lock (your own password)',
  'চালু — ব্যাকআপ খুলতে Google অ্যাকাউন্ট আর আপনার পাসওয়ার্ড দুটোই লাগে': 'On — opening the backup requires both your Google account and your password',
  'বন্ধ — Google অ্যাকাউন্ট দখল হলেও ব্যাকআপ যেন খোলা না যায়': 'Off — turn on so the backup can’t be opened even if your Google account is compromised',
  'ব্যাকআপের পাসওয়ার্ড মেলেনি। এখনকার তথ্যে কোনো পরিবর্তন হয়নি।': 'The backup password didn’t match. Nothing on this phone was changed.',
  'নিরাপত্তা কোড': 'Safety code',
  '{0}-এর ফোনেও একই কোড দেখালে আপনাদের তালা ঠিক আছে — মাঝখানে কেউ (আমাদের সার্ভারও) পড়তে পারে না। না মিললে কিছু পাঠাবেন না, আমাদের জানান।': 'If {0}’s phone shows the same code, your connection is secure — no one in between (not even our server) can read it. If it’s different, don’t send anything and let us know.',
  'অ্যাপের নতুন সংস্করণ ({0}) এসেছে — আপডেট করে আবার লগইন করুন। ফোনে রাখা সব তথ্য আগের মতোই খোলা থাকবে।': 'A new version of the app ({0}) is available — update, then sign in again. Everything on this phone stays accessible as before.',
  'নতুন সংস্করণ নামান': 'Get the update',
  'একটা পাসওয়ার্ড ৬ মাস বদলানো হয়নি': '1 password not changed in 6 months',
  '{0}টা পাসওয়ার্ড ৬ মাস বদলানো হয়নি': '{0} passwords not changed in 6 months',
  'আজ ছুটির দিন — বদলে নিলে অ্যাকাউন্ট নিরাপদ থাকে। চাপুন, ভল্টে কোনগুলো পুরোনো দেখুন।': 'It’s your day off — updating them keeps your accounts safe. Tap to see which ones are old.',
  'আগের পাসওয়ার্ড ({0}টি)': 'Previous passwords ({0})',
  '{0} পর্যন্ত চালু ছিল': 'Used until {0}',
  '{0} থেকে {1} পর্যন্ত চালু ছিল': 'Used from {0} to {1}',
  '• শেষ সম্পাদনা: {0}': '• Last edited: {0}',
  '{0} বা তার আগে': '{0} or earlier',
  'যোগ করা হয়েছে': 'Added',
  'পাসওয়ার্ড দেওয়া হয়েছে': 'Password set',
  'পাসওয়ার্ডের বয়স': 'Password age',
  '৬ মাসের বেশি পুরোনো — সম্পাদনায় গিয়ে নতুন পাসওয়ার্ড দিন; আগেরটা এখানে ঝাপসা করে রাখা থাকবে।': 'Over 6 months old — edit it and enter a new password; the old one stays here, grayed out.',
  '{0}টা পাসওয়ার্ড ৬ মাসের বেশি বদলানো হয়নি — নিচে “পুরোনো” লেখা আছে। সময় করে বদলে নিন।': '{0} passwords haven’t been changed in over 6 months — marked “Old” below. Change them when you can.',
  'পুরোনো': 'Old',
  'এই পাসওয়ার্ড এই লগইনে আগে ব্যবহার হয়েছে — নতুন একটা দিলে বেশি নিরাপদ।': 'This password was used for this login before — a new one is safer.',
  'হাঁটার হিসাব শুধু আপনার নিজের (“আমি”) ফোন থেকে পাওয়া যায়।': 'Steps are only available from your own (“Me”) phone.',
  'আজকের হাঁটার হিসাব এখনো পাইনি। স্বাস্থ্য পাতায় Health Connect (বা ফোনের ধাপ গোনা) চালু করুন — তারপর জিজ্ঞেস করলেই বলে দেবো।': 'I don’t have today’s steps yet. Turn on Health Connect (or your phone’s step counter) on the Health page — then just ask.',
  'আজ এ পর্যন্ত {0} পা হেঁটেছেন — প্রায় {1} কিমি।{2}': '{0} steps so far today — about {1} km.{2}',
  ' (Health Connect থেকে)': ' (from Health Connect)',
  ' (ফোনের ধাপ গোনা থেকে)': ' (from your phone’s step counter)',
  'ঘুমের কোনো হিসাব নেই। বলুন, যেমন “কাল রাতে ৭ ঘণ্টা ঘুমিয়েছি” — বা স্বাস্থ্য পাতায় Health Connect চালু করুন।': 'No sleep recorded. Say, for example, “I slept 7 hours last night” — or turn on Health Connect on the Health page.',
  ' গত ৭ দিনে গড়ে {0} ঘণ্টা।': ' Average over the last 7 days: {0} hours.',
  'গত রাতে {0} ঘুমিয়েছেন, উঠেছেন {1}-এ।{2}{3}': 'You slept {0} last night and woke at {1}.{2}{3}',
  'শেষ ঘুমের হিসাব {0}: {1}।{2}{3}': 'Last sleep recorded {0}: {1}.{2}{3}',
  'এই সপ্তাহে ব্যায়ামের কোনো হিসাব নেই। বলুন, যেমন “আজ ৩০ মিনিট হাঁটলাম” — বা স্বাস্থ্য পাতায় Health Connect চালু করুন।': 'No exercise recorded this week. Say, for example, “I walked 30 minutes today” — or turn on Health Connect on the Health page.',
  'আজ {0} মিনিট ব্যায়াম; গত ৭ দিনে মোট {1} মিনিট।': '{0} minutes of exercise today; {1} minutes over the last 7 days.',
  'আজ কত পা হাঁটলেন': 'Steps today',
  'হাঁটা, ঘুম আর ব্যায়ামের হিসাব নিজে থেকে আনতে Google-এর Health Connect লাগবে': 'Google Health Connect is required to import steps, sleep and exercise automatically',
  'Health Connect নামান': 'Get Health Connect',
  'Health Connect-এ অনুমতি বন্ধ আছে — আবার দিলে দেখাবে': 'Permission is turned off in Health Connect — allow it again to see this',
  'Health Connect থেকে হাঁটা, ঘুম আর ব্যায়াম — শুধু পড়বে, ফোনেই থাকবে': 'Steps, sleep and exercise from Health Connect — read-only, stored on this phone',
  'আজ {0} পা হাঁটলেন': '{0} steps today',
  'গত রাতে ঘুম {0}': 'Slept {0} last night',
  'আজ ব্যায়াম {0} মিনিট': '{0} min of exercise today',
  'Health Connect থেকে': 'From Health Connect',
  'আবার পড়ুন': 'Refresh',
  'ফোনের স্বাস্থ্য-তথ্য থেকে শুধু পড়বে': 'It only reads your phone’s health data',
  'কী পড়বে': 'What it reads',
  'হাঁটার স্টেপ, ঘুমের সময় (ঘুমের ধাপসহ) আর ব্যায়ামের সময় — শুধু “আমি”-র জন্য। কিছু লিখবে না, বদলাবে না।': 'Steps, sleep (including sleep stages) and exercise time — for “Me” only. It never writes or changes anything.',
  'কেন পড়বে': 'Why',
  'স্বাস্থ্য পাতায় “আজ কত পা হাঁটলেন”, গত রাতের ঘুম আর ব্যায়ামের মিনিট দেখাতে; আর জিজ্ঞেস করলে (“আজ কত হাঁটলাম?”, “গত রাতে কত ঘুমিয়েছি?”) আসল সংখ্যা দিয়ে উত্তর দিতে।': 'To show today’s steps, last night’s sleep and exercise minutes on the Health page, and to answer with real numbers when you ask (“How much did I walk today?”, “How long did I sleep last night?”).',
  'কোথায় থাকবে': 'Where it’s stored',
  'শুধু এই ফোনে, অ্যাপের এনক্রিপ্ট করা ফাইলে। আমাদের সার্ভারে, AI-তে বা কারও কাছে যায় না।': 'Only on this phone, in the app’s encrypted file. It’s never sent to our server, to an AI or to anyone else.',
  'হাতে লেখা': 'Entered manually',
  'হাতে বা মুখে লেখা মাপ আগের মতোই থাকবে। Health Connect থেকে আনা মাপের পাশে উৎস লেখা থাকে, একই মাপ দুবার আসে না।': 'Readings you type or say stay as before. Readings from Health Connect are labeled with their source, and the same reading is never imported twice.',
  'বন্ধ করা': 'Turning it off',
  'যেকোনো সময় এখান থেকে বা Health Connect-এর অনুমতি থেকে বন্ধ করা যায়।': 'Turn it off any time here, or in Health Connect’s permissions.',
  'পরের পাতায় Health Connect নিজে অনুমতি চাইবে। তিনটাই (স্টেপ, ঘুম, ব্যায়াম) দিলে চালু হবে।': 'Health Connect will ask for permission next. It turns on once all three (steps, sleep, exercise) are allowed.',
  'বন্ধ করে আনা মাপ মুছুন': 'Turn off and delete imported readings',
  'Health Connect থেকে আনা মাপ মুছবেন?': 'Delete readings imported from Health Connect?',
  'হাতে লেখা মাপ থাকবে। Health Connect-এ রাখা তথ্যে কিছু হবে না।': 'Manually entered readings stay. Nothing in Health Connect itself is changed.',
  'Health Connect চালু হলো': 'Health Connect is on',
  'তিনটা অনুমতিই লাগবে — আবার চেষ্টা করুন': 'All three permissions are required — try again',
  'এই ফোনে Health Connect পাওয়া যায়নি': 'Health Connect isn’t available on this phone',
  'ঠিক আছে — এই হিসাবের আয়-ব্যয় মূল হিসাবেও যোগ হবে।': 'OK — this project’s income and expenses will also be added to your main balance.',
  'ঠিক আছে — এই হিসাব আলাদা থাকবে, মূল হিসাবে যোগ হবে না।': 'OK — this project stays separate; it won’t be added to your main balance.',
  '‘{0}’ হিসাবের আয়-ব্যয় মূল হিসাবেও যোগ হবে? হ্যাঁ বললে যোগ হবে; না বললে বা উত্তর না দিলে আলাদা থাকবে।': 'Should ‘{0}’’s income and expenses also be added to your main balance? Say yes to add them; if you say no or don’t answer, it stays separate.',
  'এই হিসাবের আয়-ব্যয় মূল হিসাবেও যোগ হবে?': 'Add this project’s income and expenses to your main balance too?',
  'হ্যাঁ দিলে প্রতিটা লেনদেন মূল আয়-ব্যয় আর হাতের টাকায়ও আলাদা লাইন হয়ে যোগ হবে। না দিলে এটা আলাদা থাকবে।': 'If yes, each transaction is also added to your main Income & Expenses and cash on hand as a separate line. If no, it stays separate.',
  'হ্যাঁ, যোগ হবে': 'Yes, add it',
  'না, আলাদা থাকবে': 'No, keep it separate',
  'এখন থেকে এই হিসাবের লেনদেন মূল হিসাবেও যোগ হবে': 'From now on, this project’s transactions are also added to your main balance',
  'এই হিসাব এখন আলাদা — মূল হিসাবে যোগ হবে না': 'This project is now separate — not added to your main balance',
  'মূল হিসাব: যোগ হচ্ছে — বদলান': 'Main balance: included — Change',
  'মূল হিসাব: আলাদা — বদলান': 'Main balance: separate — Change',
  'এই হিসাবের আয় আর খরচ মূল আয়-ব্যয়েও যোগ হয়। বকেয়া পেলে নিচে বকেয়া থেকে আদায় দিন।': 'This project’s income and expenses are also added to your main Income & Expenses. When dues are paid, record them below under Dues.',
  'এই হিসাব মূল টাকার সাথে যুক্ত নয় — এর আয়, খরচ আর বকেয়া এখানেই থাকে, মূল আয়-ব্যয়ে বা যাকাতে ধরা হয় না।': 'This project isn’t linked to your main balance — its income, expenses and dues stay here and aren’t counted in your main Income & Expenses or in zakat.',
