  'ফোনের দিক-সেন্সর সাড়া দিচ্ছে না। ফোনটা বাতাসে ইংরেজি ৮-এর মতো কয়েকবার ঘোরান। তবু না হলে পাতাটা বন্ধ করে আবার খুলুন; কিছু ফোনে পাওয়ার সেভিং চালু থাকলে সেন্সর বন্ধ থাকে।': 'Your phone’s compass sensor isn’t responding. Move the phone in a figure 8 a few times. If it still doesn’t work, close and reopen the page; on some phones, battery saver turns the sensor off.',
  'ফোন সমান করে বা সামনে খাড়া করে — যেভাবে সুবিধা ধরুন; ফোনের মাথা যেদিকে, দিক সেটাই। প্রথমবার ফোনটা বাতাসে কয়েকবার ৮ আঁকার মতো ঘোরান। লোহা, চুম্বক, স্পিকার, ল্যাপটপ বা চুম্বকওয়ালা কভার থেকে দূরে রাখুন — এগুলো দিক বদলে দেয়। কিবলার দিক ফোনের লোকেশন থেকে (না পেলে বেছে নেওয়া জেলা থেকে); মসজিদের দিক মিলিয়ে নেওয়া ভালো।': 'Hold the phone flat or upright, whichever is easier; the direction is where the top of the phone points. The first time, move the phone in a figure 8 a few times. Keep it away from metal, magnets, speakers, laptops or magnetic cases — they distort the reading. The qibla is calculated from your phone’s location (or the chosen district); verify it against a local mosque.',
