  'ওয়েবসাইট': 'Website',
  'ফোনের সেন্সরে উত্তর-দক্ষিণ-পূর্ব-পশ্চিম, আর আপনি যেখানে আছেন সেখান থেকে কিবলার দিক — মিললে ফোন কেঁপে জানায়।': 'North, south, east and west from your phone’s sensor, and the qibla from your location — the phone vibrates when you face it.',
  'প্রতিটা কাজের (বাড়ি, বিয়ে, ব্যবসা) আলাদা আয়, খরচ আর বকেয়া; চাইলে মূল হিসাবে যুক্ত হয় (ফ্রিতে ১টা, প্রিমিয়ামে যত খুশি)।': 'Separate income, expenses and dues for each project (house, wedding, business); optionally linked to your main balance (1 free, unlimited with Premium).',
  'এ সপ্তাহে বা ৩০ দিনে আয়ের কত ভাগ কোন খাতে গেল — প্রয়োজনীয়, শখের, সঞ্চয়; ৫০/৩০/২০ নিয়মের সাথে মিলিয়ে কোথায় কমানো যায়।': 'How your income was spent this week or over 30 days — needs, wants, savings; compared with the 50/30/20 rule, and where to cut back.',
  'রক্তের গ্রুপ, জরুরি নম্বর (৯৯৯, ফায়ার সার্ভিস ১০২…), ওষুধ আর অ্যালার্জি।': 'Blood group, emergency numbers (999, fire service 102…), medicines and allergies.',
  'কোন বার্তা আসবে, রাতে চুপ থাকা, দিনে কয়টা।': 'Which notifications you get, quiet hours at night, how many per day.',
