  'Google Play-র মাধ্যমে কেনা হয়; Google Play থেকে যেকোনো সময় বন্ধ করা যায়। প্রিমিয়াম আপনার Google অ্যাকাউন্টের সাথে থাকে — নতুন ফোনেও পাবেন।': 'Purchased through Google Play; cancel any time on Google Play. Premium is linked to your Google account, so you keep it on a new phone too.',
