  'এই Google অ্যাকাউন্টে প্রিমিয়াম আগেই কেনা আছে — “আগে কেনা প্রিমিয়াম ফিরিয়ে আনুন” চাপুন': 'Premium has already been purchased on this Google account — tap “Restore a previous purchase”',
  'Google Play-তে কেনা হয়নি — পরে আবার চেষ্টা করুন': 'Purchase not completed on Google Play — try again later',
  'Google Play-তে কেনা হয়নি': 'Purchase not completed on Google Play',
  'এই ফোনের Google Play অ্যাকাউন্টে কোনো প্রিমিয়াম কেনা পাওয়া যায়নি': 'No Premium purchase found on this phone’s Google Play account',
  'এই কেনার মেয়াদ শেষ বা ফেরত হয়েছে — Google Play-তে দেখুন': 'This purchase has expired or been refunded — check Google Play',
  'এই কেনাটা অন্য একটা অ্যাকাউন্টের — সেই Google অ্যাকাউন্ট দিয়ে লগইন করুন': 'This purchase belongs to another account — sign in with that Google account',
  'Google এই কেনাটা চিনতে পারেনি': 'Google couldn’t verify this purchase',
  'অ্যাকাউন্ট মুছবেন?': 'Delete account?',
  'আমাদের সার্ভারে এই অ্যাকাউন্টের সব তথ্য মুছে যাবে — প্রিমিয়াম, ফ্যামিলি, রক্তের গ্রুপ, মতামত আর লগ। এটা ফেরানো যায় না। Google Play-তে কেনা সাবস্ক্রিপশন থাকলে Google Play থেকে আলাদা করে বন্ধ করুন। ফোনে রাখা তথ্য আর আপনার Drive-এর ব্যাকআপ থেকে যাবে।': 'All data our server stores for this account will be deleted — Premium, Family, blood group, feedback and logs. This can’t be undone. A subscription purchased on Google Play must be canceled separately on Google Play. Data on your phone and your Drive backup are kept.',
  'অ্যাকাউন্ট মুছে ফেলা হয়েছে': 'Account deleted',
  'অ্যাকাউন্ট মুছুন': 'Delete account',
  'প্রাইভেসি পলিসি': 'Privacy policy',
  'কোন তথ্য ফোনেই থাকে, কোনটা কেন সার্ভারে যায়': 'What stays on your phone, and what is sent to the server and why',
  'বিজ্ঞাপনের গোপনীয়তা': 'Ad privacy',
  'Google বিজ্ঞাপনের জন্য আপনার সম্মতি বদলান': 'Change your consent for Google ads',
  'নতুন সংস্করণ এসেছে': 'A new version is available',
  'My Assistant-এর নতুন সংস্করণ Google Play-তে এসেছে। আপডেট করলে নতুন সুবিধা আর ঠিক করা ভুলগুলো পাবেন। আপনার সব তথ্য ফোনে আগের মতোই থাকবে।': 'A new version of My Assistant is available on Google Play. Update to get the latest features and fixes. Everything on your phone stays as it is.',
  'এখন আপডেট করুন': 'Update now',
  'আপডেট হচ্ছে… শেষ হলে অ্যাপ নিজেই আবার খুলবে।': 'Updating… the app will reopen automatically when it’s done.',
  'আপডেট বাতিল হয়েছে। চাইলে আবার চাপুন।': 'The update was canceled. Tap again to retry.',
  'এখন আর কোনো আপডেট নেই।': 'No updates available.',
  'আপডেট শুরু করা গেল না। Play Store থেকে My Assistant খুলে আপডেট করুন।': 'The update couldn’t start. Open My Assistant in the Play Store and update it there.',
  'আপনার তথ্য': 'Your data',
  'রিমাইন্ডার ও নোটিফিকেশন': 'Reminders and notifications',
  'ফোনে কথা বোঝা': 'On-device understanding',
  'কেন, কীভাবে শিখছে, কী উন্নতি হলো': 'Why, how it learns, what’s improved',
  'কিছু বার্তা নাম সরিয়ে সার্ভারে যায় — পাসওয়ার্ড, ফোন নম্বর, কোড বা স্বাস্থ্যের কথা কখনো না; ১৮০ দিন পর নিজে মুছে যায়': 'Some messages are sent to the server with names removed — never passwords, phone numbers, codes or health information; automatically deleted after 180 days',
  'কী নিই, কেন নিই — আর মুছে দেওয়া': 'What we collect, why — and how to delete it',
  'সাহায্য ও যোগাযোগ': 'Help and contact',
  'এই ফোনে চলছে · সংস্করণ {0}': 'Running on this phone · version {0}',
  'কেন নিজের মডেল': 'Why we built our own model',
  'আমরা চাই My Assistant সবাই বিনা মূল্যে ব্যবহার করতে পারুক। আপনার প্রতিটা কথা বড় ক্লাউড AI দিয়ে বোঝাতে হলে প্রতিবার খরচ হয় — সেই খরচ শেষে ব্যবহারকারীকেই দিতে হতো।': 'We want everyone to be able to use My Assistant for free. Having a large cloud AI process everything you say costs money every time — and eventually users would have to pay for it.',
  'তাই আমরা নিজেরা একটা ছোট মডেল বানাচ্ছি, যা আপনার ফোনের ভেতরেই চলে। এতে কোনো খরচ নেই, ইন্টারনেট ছাড়াও কাজ করে, আর আপনার কথা ফোনের বাইরে যায় না।': 'So we’re building our own small model that runs on your phone. It costs nothing, works offline, and your words never leave the phone.',
  'এটা কীভাবে বোঝে': 'How it understands',
  'আপনি যা বলেন বা লেখেন, তা একসাথে দুজন পড়ে — অ্যাপের নিজের নিয়ম আর এই মডেল। দুজন একমত হলে সেটাই করা হয়।': 'Two systems read what you say or type at the same time — the app’s built-in rules and this model. When they agree, that’s what happens.',
  'একমত না হলে, দরকার হলে আমাদের সার্ভার থেকে তৃতীয় একটা মত নেওয়া হয় — নাম সরিয়ে। তিনজনের দুজন যা বলে, সেটাই। পাসওয়ার্ড, ফোন নম্বর, কোড বা স্বাস্থ্য-ওষুধের কথা থাকলে কখনো বাইরে যায় না — ফোনেই সিদ্ধান্ত হয়।': 'When they don’t, a third opinion may be requested from our server — with names removed — and the majority decides. Anything involving passwords, phone numbers, codes, health or medicines is never sent; the phone decides on its own.',
  'দিনে দিনে কীভাবে শিখছে': 'How it learns, round by round',
  'নমুনা': 'Samples',
  'যেসব কথায় নিয়ম আর মডেল একমত হয়নি, তার কিছু নাম সরিয়ে সার্ভারে আসে। পাসওয়ার্ড, ফোন নম্বর, কোড, স্বাস্থ্য বা ওষুধের কথা কখনো না; ১৮০ দিন পর নিজে মুছে যায়।': 'Some sentences that the rules and the model read differently are sent to the server with names removed. Never passwords, phone numbers, codes, health or medicines; automatically deleted after 180 days.',
  'সঠিক অর্থ': 'Correct labeling',
  'প্রতিটা বাক্যের সঠিক অর্থ আমরা মিলিয়ে লিখি — কোনটা কাজ, কোনটা রিমাইন্ডার, কোনটা টাকার হিসাব।': 'We record what each sentence actually meant — a task, a reminder, money.',
  'নতুন করে শেখানো': 'Retraining',
  'এসব আর হাজার হাজার বাক্য দিয়ে নতুন মডেল শেখানো হয়।': 'A new model is trained on these and thousands of other sentences.',
  'কড়া পরীক্ষা': 'Strict testing',
  'প্রায় ৭ হাজার বাক্যের আলাদা পরীক্ষায় — যে বাক্য শেখানোয় কখনো দেওয়া হয় না। কোনো ধরনের কথায় আগের চেয়ে স্পষ্ট খারাপ করলে নতুন মডেল বাতিল।': 'It’s tested on a separate set of about 7,000 sentences that are never used for training. If it performs clearly worse than before on any type of request, the new model is rejected.',
  'অল্প অল্প করে চালু': 'Gradual rollout',
  'পরীক্ষায় পাস করলে আগে কিছু ফোনে, ঠিক থাকলে সবার ফোনে — Wi-Fi পেলে নিজে নামে। সমস্যা হলে আগের মডেলে ফেরা যায়।': 'If it passes, it rolls out to some phones first, then to everyone — it downloads automatically over Wi-Fi. If there’s a problem, we roll back to the previous model.',
  'এই মডেলে কী উন্নতি হয়েছে': 'What’s improved in this model',
  'সংস্করণ {0}-এর হিসাব এখনো এখানে যোগ হয়নি।': 'Results for version {0} haven’t been added yet.',
  'মডেল নামলে এখানে দেখাবে, আগের সংস্করণের চেয়ে কোথায় কতটা ভালো।': 'Once the model is downloaded, this shows where and by how much it improves on the previous version.',
  'আগের সংস্করণের সাথে তুলনা — একই পরীক্ষায়, কতটা ঠিক বুঝেছে:': 'Compared with the previous version — accuracy on the same test:',
  'লেখা বাক্যের পরীক্ষায় মাপা। মুখে বললে ফোনের মাইক কতটা ঠিক শোনে, তার ওপরও নির্ভর করে।': 'Measured on written sentences. For speech, it also depends on how well your phone’s microphone hears you.',
  'আপনি কীভাবে সাহায্য করবেন': 'How you can help',
  'ভুল বুঝলে আমাদের জানান': 'Tell us when it gets something wrong',
  'কী বলেছিলেন আর কী হলো — লিখে দিন': 'Describe what you said and what happened',
  'পাঠানো বার্তা মুছে দেবেন?': 'Delete sent messages?',
  'সার্ভারে আপনার পাঠানো সব বার্তা মুছে যাবে, আর এখন থেকে পাঠানো বন্ধ থাকবে। চাইলে পরে “ফোনে কথা বোঝার মডেল” পাতা থেকে আবার চালু করতে পারবেন।': 'All messages you sent will be deleted from the server, and sending will stop from now on. You can turn it back on later on the “On-device understanding” page.',
  'মুছে দিন': 'Delete',
  'মুছে দেওয়া হয়েছে — আর পাঠানো হবে না': 'Deleted — nothing more will be sent',
  'আমার পাঠানো বার্তা': 'Messages I’ve sent',
  'এখন পাঠানো চালু আছে।': 'Sending is currently on.',
  'এখন পাঠানো বন্ধ আছে।': 'Sending is currently off.',
  'কী নিই': 'What we collect',
  'যেসব কথায় অ্যাপের নিয়ম আর ফোনের মডেল একমত হয়নি, তার কিছু বাক্য — আর একমত হওয়া কথার প্রতি দশটার একটা।': 'Some sentences that the app’s rules and the on-device model read differently — and one in ten of those they agreed on.',
  'বাক্যের নামগুলো ফোনেই সরিয়ে “<নাম১>” বসানো হয়।': 'Names in a sentence are replaced on your phone with “<name1>”.',
  'সাথে যায়: অ্যাপ আর মডেলের সংস্করণ, অ্যাপ তখন কী জানতে চাইছিল, আর কে কী বুঝেছিল।': 'Also included: the app and model versions, what the app was asking at the time, and what each one understood.',
  'কী কখনো নিই না': 'What we never collect',
  'পাসওয়ার্ড, PIN, OTP বা কোনো লম্বা কোড': 'Passwords, PINs, OTPs or any long code',
  'ফোন নম্বর': 'Phone numbers',
  'স্বাস্থ্য, ওষুধ, ভল্ট বা কন্টাক্টের কথা': 'Anything about health, medicines, the vault or contacts',
  'আপনার নাম বা ইমেইল — নমুনার সাথে শুধু একটা গোপন সংকেত থাকে, যাতে আপনি চাইলে আপনারগুলো মুছে দেওয়া যায়': 'Your name or email — each sample carries only an anonymous ID, so your data can be deleted on request',
  'কেন নিই': 'Why we collect it',
  'অ্যাপ সবার জন্য বিনা মূল্যে রাখতে আমরা ফোনের ভেতরে চলা নিজের মডেল বানাচ্ছি। মানুষ আসলে যেভাবে বলে, সেই বাক্য দিয়েই মডেল সবচেয়ে ভালো শেখে।': 'To keep the app free for everyone, we’re building our own model that runs on the phone. It learns best from how people actually speak.',
  'এই বাক্য শুধু মডেল শেখানো আর পরীক্ষার কাজে লাগে — বিক্রি হয় না, বিজ্ঞাপনে যায় না।': 'These sentences are used only to train and test the model — never sold, never used for ads.',
  'কতদিন থাকে': 'How long it’s kept',
  '১৮০ দিন পর নিজে মুছে যায়। তার আগেই মুছতে চাইলে নিচে চাপুন।': 'Automatically deleted after 180 days. To delete sooner, tap below.',
