  ' নিচের “{0}” মেনুতে পাবেন।': ' You’ll find it in the “{0}” menu at the bottom.',
  'ব্যবসায়ী মোড (প্রিমিয়াম): দোকান চালানোর আলাদা মোড — হোম, বিক্রি, গ্রাহক, হিসাব আর স্টক; ব্যবসার আয়-ব্যয় নিজের আয়-ব্যয় থেকে আলাদা থাকে, যাকাতে “ব্যবসা থেকে” লেখা থাকে। “আরও” মেনুতে ব্যবসায়ী মোড চালু করুন।': 'Business mode (Premium): a separate mode for running a shop — Home, Sales, Customers, Money and Inventory; business money is kept separate from your personal finances, and zakat marks it “From business”. Turn it on in the “More” menu.',
  'বিক্রি: পণ্য বেছে বিক্রি, ছাড় টাকায় বা শতাংশে, নগদ/QR/বাকিতে; বিক্রির পরে PDF রসিদ হোয়াটসঅ্যাপে পাঠানো যায়। ব্যবসায়ী মোডের “বিক্রি” ট্যাবে।': 'Sales: choose products, apply a discount in taka or percent, take cash, QR or credit; after a sale, a PDF receipt can be sent via WhatsApp. In the “Sales” tab of Business mode.',
  'গ্রাহক: প্রতিটা গ্রাহকের প্রোফাইল, কেনাকাটা আর বাকি; বাকির রিমাইন্ডার আর হোয়াটসঅ্যাপে তাগাদা। ব্যবসায়ী মোডের “গ্রাহক” ট্যাবে।': 'Customers: each customer’s profile, purchases and dues; dues reminders and WhatsApp payment reminders. In the “Customers” tab of Business mode.',
  'ব্যবসার হিসাব: ব্যবসার আয়-ব্যয়, আজকের নগদ, ডিলারের কাছ থেকে মাল কেনা আর পরিশোধ। ব্যবসায়ী মোডের “হিসাব” ট্যাবে।': 'Business finances: business income and expenses, today’s cash, inventory purchased from suppliers and payments to them. In the “Money” tab of Business mode.',
  'স্টক: পণ্যের স্টক, কেনা-বেচার দাম, ধরন ধরে সেকশন; কম পড়লে অর্ডারের তালিকায় ওঠে। ব্যবসায়ী মোডের “স্টক” ট্যাবে।': 'Inventory: products in stock, cost and selling prices, categories by type; low-stock items are added to the order list. In the “Inventory” tab of Business mode.',
