  'দিনের হিসাব দিনেই লিখুন — কাল আর মনে থাকে না।': 'Record today’s accounts today — tomorrow you won’t remember.',
  'ছোট লাভে বেশি বিক্রি, বড় লাভে কম ক্রেতা।': 'Small margins bring more sales; big margins bring fewer buyers.',
  'মেয়াদ শেষের আগে কম দামে বিক্রি — ফেলে দেওয়ার চেয়ে ভালো।': 'Sell near-expiry stock at a discount — better than throwing it away.',
