  'এই ফোনে খোলা গেল না — যে ফোনে পরিবার চালু করেছিলেন সেখানে খুলুন, অথবা তাঁর পাঠানো নতুন কপির জন্য অপেক্ষা করুন': 'Couldn’t open on this phone — open it on the phone you joined Family with, or wait for them to send a new copy',
  'ফ্রিতে ১টা আলাদা হিসাব খোলা যায়, সেটা খোলা আছে; আরও খুলতে প্রিমিয়াম লাগবে। নতুনটা খোলা হয়নি।': 'The free plan includes 1 project, which you already have; more require Premium. The new one wasn’t created.',
  'দিনের কথা লিখে রাখা; নিচে অভ্যাস, বিশেষ দিন আর রেডিমেড তালিকা।': 'Write about your day; below it are habits, special days and ready-made checklists.',
  'দিনের কাজ, বাজারের লিস্ট; টিক দিলে শেষ। তালিকা হোয়াটসঅ্যাপে পাঠানো যায়।': 'Daily tasks and shopping lists; tick off when done. Share lists on WhatsApp.',
  'যা মনে রাখতে চান; বিভাগ ধরে সাজানো, ছবি-ফাইল যোগ করা যায়, টিক-চিহ্নের তালিকাও। উপরে ওসিয়তনামা।': 'Anything you want to remember, organized by category, with photos and files, or as a checklist. Your will is at the top.',
  'ওসিয়তনামা': 'Will',
  'নিজের ওসিয়ত লিখে রাখা, কবে শেষ বদলেছেন তারিখসহ; উত্তরাধিকারী পরে দেখতে পান (প্রিমিয়াম)।': 'Write your will, with the date it was last changed; your heir can see it later (Premium).',
  'নাম বললেই ফোন, SMS বা হোয়াটসঅ্যাপ; নম্বর, ঠিকানা (ম্যাপে খোলে) আর কাগজ একসাথে।': 'Say a name to call, SMS or WhatsApp; numbers, addresses (open in Maps) and documents in one place.',
  '“এখন আছে” কত টাকা আর কীভাবে হলো; নিজের আয় আর খরচ খাত ধরে; ধার আর আলাদা হিসাবের টাকা নিজে যুক্ত হয়।': 'Your current balance and how it was calculated; your own income and expenses by category; loans and Projects are linked automatically.',
  'কে কত পাবে, কাকে কত দিতে হবে, বকেয়াসহ; ফেরতের তারিখে মনে করায়; এক চাপে মনে করিয়ে দেওয়ার মেসেজ।': 'Who owes what, including dues; a reminder on the repayment date; a payment reminder message in one tap.',
  'দোকানের নাম, নম্বর, ঠিকানা; বিক্রি, খরচ, গ্রাহকের বাকি আর রসিদ।': 'Shop name, phone number, address; sales, costs, customer dues and receipts.',
  'দিনের কথা লিখে রাখা; নিচে অভ্যাস, ওষুধ, বিশেষ দিন আর রেডিমেড তালিকা।': 'Write about your day; habits, medicines, special days and ready-made checklists below.',
  'রেডিমেড তালিকা': 'Ready-made checklists',
  'যত খুশি রিমাইন্ডার, ডকুমেন্ট আর পাসওয়ার্ড; আলাদা হিসাব, ওসিয়তনামা, পরিবারের স্বাস্থ্য, উত্তরাধিকার ও লোকেশন, অটো ব্যাকআপ, PDF, AI উত্তর — বিজ্ঞাপন ছাড়া। পেমেন্ট বিকাশে।': 'Unlimited reminders, documents and passwords; Projects, will, family health, heirs and location, automatic backup, PDF, AI answers — no ads. Pay with bKash.',
  'বকেয়া — পাব {0}, দেব {1}': 'Dues — owed to me {0}, I owe {1}',
  'আপডেট: {0}': 'Updated: {0}',
  'সাথে {0}টা ফাইল (অ্যাপে আছে)': '{0} file(s) attached (in the app)',
  'গোপন তথ্য (পাসওয়ার্ড/PIN) থাকা {0}টা নোট এই PDF-এ রাখা হয়নি।': '{0} note(s) containing secrets (passwords/PINs) were excluded from this PDF.',
  '{0}টা (~{1} দিন)': '{0} (~{1} days)',
  '{0} কোনো তথ্য নেই। তথ্যটি যুক্ত করতে পারেন — বলুন, যেমন “{1}”। পরে যেকোনো সময় জিজ্ঞেস করলে উত্তর দেব।': 'There’s no information on {0}. You can add it — say, e.g., “{1}”. Then ask me any time.',
  'আপনার নামের কোনো তথ্য নেই। সেটিংসে প্রোফাইলে নামটি যুক্ত করতে পারেন — তারপর নাম ধরেই কথা বলব।': 'No name saved. Add it to your profile in Settings and I’ll use it.',
  'আপনার জন্মতারিখের কোনো তথ্য নেই। স্বাস্থ্য পাতায় “বদলান” চেপে জন্মতারিখ দিতে পারেন — তারপর জিজ্ঞেস করলেই বয়স বলে দেব।': 'No date of birth saved. Add it on the Health page (tap Edit) and I’ll tell you your age whenever you ask.',
  'আপনার জন্মতারিখের কোনো তথ্য নেই। স্বাস্থ্য পাতায় “বদলান” চেপে জন্মতারিখ দিতে পারেন — পরে যেকোনো সময় জিজ্ঞেস করলে উত্তর দেব।': 'No date of birth saved. Add it on the Health page (tap Edit), then ask me any time.',
  'আপনার অ্যালার্জির কোনো তথ্য নেই। জরুরি কার্ডে তথ্যটি যুক্ত করতে পারেন — পরে যেকোনো সময় জিজ্ঞেস করলে উত্তর দেব।': 'No allergy information yet. Add it to your emergency card, then ask me any time.',
  'আপনার কোনো রোগের তথ্য নেই। জরুরি কার্ডে তথ্যটি যুক্ত করতে পারেন — পরে যেকোনো সময় জিজ্ঞেস করলে উত্তর দেব।': 'No medical conditions recorded. Add them to your emergency card, then ask me any time.',
  'বুঝেছি — কাজগুলো আলাদা আলাদা হবে। আগের কথাটা আবার বলুন, শুরুতে দিন আর “কাজ”, তারপর কমা দিয়ে একেকটা কাজ — যেমন “১০ জানুয়ারি কাজ গুলো, রবিনকে কল করব, নাস্তা করব, মসজিদে যাব”। প্রতিটা আলাদা কাজ হিসেবে রাখব।': 'Got it — they should be separate to-dos. Say it again with the day and “to-dos” first, then each to-do separated by a comma — e.g. “10 January to-dos, call Robin, have breakfast, go to the mosque”. Each will be saved separately.',
  'আপনার তথ্য আপনার ফোনেই থাকে, PIN দিয়ে তালা দেওয়া। পাসওয়ার্ড, পিন আর ওটিপি কখনো ফোনের বাইরে যায় না। ব্যাকআপ যায় আপনার নিজের Google Drive-এ, তালা দেওয়া অবস্থায়। পরিবারে কিছু পাঠালে শুধু সেই মানুষটাই খুলতে পারেন। কথা বুঝতে সাহায্য লাগলে শুধু সেই কথাটুকু আমাদের সার্ভারে যায়।': 'Your data stays on your phone, locked with your PIN. Passwords, PINs and OTPs never leave the phone. Backups go to your own Google Drive, encrypted. Anything you send in Family can only be opened by that person. When help is needed to understand something you said, only those words are sent to our server.',
  'টাকার হিসাবের কোনো তথ্য নেই। অ্যাকাউন্ট পাতায় হাতের টাকা, বিকাশ, ব্যাংকের জমা যুক্ত করতে পারেন — পরে জিজ্ঞেস করলেই কোথায় কত আছে বলে দেব।': 'No balance information yet. Add cash in hand, bKash and bank balances on the Accounts page and I’ll tell you where your money is whenever you ask.',
  'আপনার হিসাব থেকে যাকাতযোগ্য সম্পদ এখন প্রায় {0} টাকা (নগদ, ব্যাংক-সঞ্চয়, পাওনা থেকে দেনা বাদে)। নিসাব জানতে আজকের রুপার দাম লাগবে — যাকাত পাতায় রুপার দাম আর সোনা-রুপার পরিমাণ দিন, তারপর জিজ্ঞেস করলেই যাকাত বলে দেব।': 'From your records, your zakatable wealth is about ৳{0} (cash, bank and savings, money owed to you, minus debts). For the nisab I need today’s silver price — enter it along with your gold and silver on the Zakat page, then ask again.',
  'সঞ্চয়ের কোনো তথ্য নেই। “সঞ্চয় ও কিস্তি” পাতায় লক্ষ্য যুক্ত করতে পারেন — পরে জিজ্ঞেস করলেই কত জমল বলে দেব।': 'No savings information yet. Add a goal on the Savings page and I’ll tell you how much you’ve saved whenever you ask.',
  'ওষুধের কোনো তথ্য নেই। ওষুধ পাতায় নাম আর খাওয়ার সময় যুক্ত করতে পারেন — সময়মতো মনে করিয়ে দেব।': 'No medicines yet. Add the name and times on the Medicines page and I’ll remind you on time.',
  'অভ্যাসের কোনো তথ্য নেই। অভ্যাস পাতায় যুক্ত করতে পারেন — প্রতিদিন টিক দিলে কত দিন টানা হলো বলে দেব।': 'No habits yet. Add habits on the Habits page — tick them daily and I’ll tell you your streak.',
  'কোনো নোট নেই। বলুন “মনে রাখো: …” — রেখে দেব, পরে জিজ্ঞেস করলেই বলব।': 'No notes. Say “Remember: …” — I’ll save it and tell you whenever you ask.',
  'বিশেষ দিনের কোনো তথ্য নেই। বলুন, যেমন “রহিমের জন্মদিন ১২ মার্চ” — প্রতি বছর মনে করিয়ে দেব।': 'No special days yet. Say, for example, “Rahim’s birthday is on 12 March” and I’ll remind you every year.',
  'আপনি রেখেছিলেন: {0}। ডকুমেন্টসে কাগজটি রেখে মেয়াদের তারিখ দিলে শেষ হওয়ার আগে মনে করিয়ে দেব।': 'You saved: {0}. Add the document to Documents with its expiry date and I’ll remind you before it expires.',
  'মেয়াদের কোনো তথ্য নেই। ডকুমেন্টসে কাগজটি রেখে মেয়াদের তারিখ দিলে শেষ হওয়ার আগে মনে করিয়ে দেব।': 'No expiry information. Save the document in Documents with its expiry date and I’ll remind you before it expires.',
  'ওজনের কোনো তথ্য নেই। বলুন, যেমন “আজ ওজন ৬৮ কেজি” — পরে যেকোনো সময় জিজ্ঞেস করলে হিসাব দেব।': 'No weight information. Say, for example, “My weight is 68 kg today”, then ask me any time.',
  'প্রেশারের কোনো তথ্য নেই। মেপে বলুন, যেমন “প্রেশার ১৩০ বাই ৮৫” — পরে যেকোনো সময় জিজ্ঞেস করলে হিসাব দেব।': 'No blood pressure records. Measure it and say, for example, “Blood pressure 130 over 85”, then ask me any time.',
  'সুগারের কোনো তথ্য নেই। মেপে বলুন, যেমন “খালি পেটে সুগার ৬.৮” — পরে যেকোনো সময় জিজ্ঞেস করলে হিসাব দেব।': 'No blood sugar readings yet. Measure it and say, for example, “Fasting sugar 6.8”, then ask me any time.',
  'আজকের হাঁটার হিসাব এখনো পাইনি। স্বাস্থ্য পাতায় Health Connect (বা ফোনের ধাপ গোনা) চালু করুন — তারপর জিজ্ঞেস করলেই বলে দেব।': 'I don’t have today’s steps yet. Turn on Health Connect (or your phone’s step counter) on the Health page — then just ask.',
  'স্বাস্থ্যের কোনো মাপ এখনো রাখা নেই। বলুন, যেমন “আজ ওজন ৬৮ কেজি” বা “প্রেশার ১৩০ বাই ৮৫” — তারপর জিজ্ঞেস করলে অবস্থা বলে দেব।': 'No health readings yet. Say, for example, “My weight is 68 kg today” or “Blood pressure 130 over 85” — then ask me and I’ll tell you how you’re doing.',
  '{0}টা পণ্য, মোট {1} একক — বিক্রয়মূল্যে; ব্যবসায়ী মোডের স্টক থেকে': '{0} products, {1} units in total — at selling price; from Business mode inventory',
  'Wi-Fi-এর কোনো তথ্য নেই। পাসওয়ার্ড ভল্টে তথ্যটি যুক্ত করতে পারেন — পরে জিজ্ঞেস করলে আঙুলের ছাপ নিয়ে দেখাব।': 'No Wi-Fi details found. Add them to the Password Vault — when you ask, I’ll show them after you verify with your fingerprint.',
  'কোনো পাসওয়ার্ডের তথ্য নেই। পাসওয়ার্ড ভল্টে তথ্যটি যুক্ত করতে পারেন — পরে জিজ্ঞেস করলে আঙুলের ছাপ নিয়ে দেখাব।': 'No passwords saved. Add them to the Password Vault — when you ask, I’ll show them after you verify with your fingerprint.',
  'এ বিষয়ে কোনো তথ্য নেই। তথ্যটি যুক্ত করতে পারেন — বলুন “মনে রাখো: …” — পরে যেকোনো সময় জিজ্ঞেস করলে উত্তর দেব।': 'No information on that. You can add it — say “Remember: …” — and I’ll answer whenever you ask.',
  '{0} নম্বরের কোনো তথ্য নেই। বলুন “{0} নম্বর ০১৭… রাখো”, অথবা যোগাযোগ পাতা থেকে ফোনবুকের নম্বর আনুন — পরে নাম বললেই ফোন করে দেব।': 'No number saved for {0}. Say “Save {0}’s number 017…”, or import your phone book on the Contacts page — then just say the name and I’ll call.',
  'এখনো অন্যান্য কোনো হিসাব খোলা হয়নি। বলুন, যেমন “মৃত্তিকা ফাউন্ডেশন নামে আলাদা হিসাব খোলো”।': 'No projects yet. Say, for example, “Create a project called Mrittika Foundation”.',
  'আলাদা হিসাব {0}টা:': '{0} projects:',
  'এই মাসের আয়-খরচের কোনো তথ্য নেই। বলুন, যেমন “বাজারে ৫০০ টাকা খরচ হলো” — পরে জিজ্ঞেস করলেই হিসাব দেব।': 'No income or expenses this month. Say, for example, “Spent 500 taka on groceries”, and ask me any time.',
  'জন্মদিন, বিবাহবার্ষিকী, মৃত্যুবার্ষিকী — রেখে দিন, প্রতি বছর আগের দিন আর সেদিন সকালে মনে করিয়ে দেব। মুখেও বলা যায়: “রহিমের জন্মদিন ১২ মার্চ”।': 'Birthdays, wedding anniversaries, death anniversaries — save them and I’ll remind you every year, the day before and that morning. You can also say: “Rahim’s birthday is on 12 March”.',
  'কবে মনে করাব': 'Reminder date',
  'আমাদের সার্ভারে এই অ্যাকাউন্টের সব তথ্য মুছে যাবে — প্রিমিয়াম, পরিবার, রক্তের গ্রুপ, মতামত আর লগ। এটা ফেরানো যায় না। Google Play-তে কেনা সাবস্ক্রিপশন থাকলে Google Play থেকে আলাদা করে বন্ধ করুন। ফোনে রাখা তথ্য আর আপনার Drive-এর ব্যাকআপ থেকে যাবে।': 'All data our server stores for this account will be deleted — Premium, Family, blood group, feedback and logs. This can’t be undone. A subscription purchased on Google Play must be canceled separately on Google Play. Data on your phone and your Drive backup are kept.',
  'ব্যাকআপে আছে: {0}টা পাসওয়ার্ড, {1} জন যোগাযোগ, {2}টা ধার-দেনা, {3}টা আয়-ব্যয়, {4}টা নোট, {5}টা রিমাইন্ডার, {6}টা কাজ।\n\nএখনকার সব তথ্য এর বদলে যাবে (মেশানো হবে না)।': 'The backup contains: {0} passwords, {1} contacts, {2} loans, {3} income & expense entries, {4} notes, {5} reminders, {6} tasks.\n\nEverything currently on the phone will be replaced (not merged).',
  'এই ব্যাকআপ অ্যাপের নতুন সংস্করণে বানানো। আগে অ্যাপ আপডেট করুন।': 'This backup was created by a newer version. Update the app first.',
  'ব্যাকআপে আছে: {0}টা পাসওয়ার্ড, {1} জন যোগাযোগ, {2}টা ধার-দেনা, {3}টা আয়-ব্যয়, {4}টা নোট, {5}টা রিমাইন্ডার, {6}টা কাজ, {7}টা ছবি/ফাইল।\n\nএখনকার সব তথ্য এর বদলে যাবে (মেশানো হবে না)। কিছু ব্যর্থ হলে এখনকার তথ্য যেমন আছে থাকবে।': 'The backup contains: {0} passwords, {1} contacts, {2} loans, {3} income & expense entries, {4} notes, {5} reminders, {6} tasks, {7} photos/files.\n\nEverything currently on the phone will be replaced (not merged). If anything fails, your current data stays as it is.',
  'এই ব্যাকআপ অ্যাপের নতুন সংস্করণে বানানো। আগে অ্যাপ আপডেট করুন। এখনকার তথ্যে কোনো পরিবর্তন হয়নি।': 'This backup was created by a newer version of the app. Update the app first. Nothing was changed.',
  '{0}টা · তালাবদ্ধ': '{0} · locked',
  'আগের পাসওয়ার্ড ({0}টা)': 'Previous passwords ({0})',
  'আপনাকে কী নামে ডাকব?': 'What should I call you?',
  'ফোনে কোনো বাংলা কণ্ঠ পাওয়া যায়নি। Play Store থেকে “Speech Services by Google” আপডেট করে, ফোনের Settings › ভাষা › Text-to-speech থেকে বাংলা (বাংলাদেশ) কণ্ঠ ডাউনলোড করে নিন।': 'No Bangla voice found on the phone. Update “Speech Services by Google” from the Play Store, then download the Bangla (Bangladesh) voice under Settings › Language › Text-to-speech.',
  'কথা বোঝার মডেল': 'On-device language model',
  'কিছু বার্তা নাম সরিয়ে সার্ভারে যায় — পাসওয়ার্ড, মোবাইল নম্বর, কোড বা স্বাস্থ্যের কথা কখনো না; ১৮০ দিন পর নিজে মুছে যায়': 'Some messages are sent to the server with names removed — never passwords, phone numbers, codes or health information; automatically deleted after 180 days',
  'কথা বোঝা': 'On-device understanding',
  'রাখা হয়নি': 'Not saved',
  '“শেয়ার” চেপে Google Drive বা নিজের হোয়াটসঅ্যাপে পাঠিয়ে রাখুন — ফোন হারালেও ফাইল থাকবে।': 'Tap “Share” and send it to Google Drive or to yourself on WhatsApp — the file stays safe even if you lose your phone.',
  '{0}টা বেছে নিয়েছেন — কীভাবে রাখব?': 'You selected {0} — how should I save them?',
  'পাঠানো হয়েছে। ধন্যবাদ — উত্তর এলে জানাব।': 'Sent. Thank you — we’ll notify you when we reply.',
  '{0}টা কথা মনে রাখা আছে': '{0} things remembered',
  'এখনো লেখা হয়নি — নিজের ওসিয়ত লিখে রাখুন': 'Not written yet — write your will',
  'শেষ ওসিয়ত: {0}': 'Will last updated: {0}',
  'বিসমিল্লাহির রাহমানির রাহীম।\n\nআমি, {0}, সুস্থ মস্তিষ্কে, কারো চাপ ছাড়া এই ওসিয়ত করছি।\n\n১. আমার দেনা: …\n২. আমার পাওনা: …\n৩. আমার সম্পদের এক-তৃতীয়াংশের মধ্যে ওসিয়ত: …\n৪. জানাজা ও দাফন: …\n৫. পরিবারের জন্য কথা: …\n\nবাকি সম্পদ ইসলামি উত্তরাধিকার আইন অনুযায়ী ভাগ হবে।': 'Bismillahir Rahmanir Rahim.\n\nI, {0}, being of sound mind and under no pressure, make this will.\n\n1. My debts: …\n2. Money owed to me: …\n3. Bequests (within one-third of my estate): …\n4. Janazah and burial: …\n5. Words for my family: …\n\nThe rest of my estate is to be divided according to Islamic inheritance law.',
  'ওসিয়তনামা রাখা হলো — {0}': 'Will saved — {0}',
  'এই ফোনে তালাবদ্ধ থাকে। পরিবারে উত্তরাধিকারী রাখলে আর “নোট” দেখার অনুমতি দিলে তিনি পরে দেখতে পাবেন। বদলালে নতুন তারিখ দেখাবে।': 'Encrypted on this phone. If you add an heir in Family and allow them to see notes, they can read it later. Editing it updates the date.',
  'আপনার ওসিয়ত এখানে লিখুন…': 'Write your will here…',
  'হাতে, ব্যাংকে, বিকাশে — সব মিলিয়ে লিখুন। এরপর আয়, খরচ, ধার আর আলাদা হিসাবের খরচ লিখলে নিজে বাড়বে-কমবে।': 'Cash, bank, bKash — enter the combined total. After that it goes up and down with your income, expenses, loans and Project spending.',
  'ধার দিলে ব্যয়ে দেখায়, ধার নিলে আয়ে — খরচ বা আয় নয়, টাকা আসা-যাওয়া। আলাদা হিসাবের খরচ এখান থেকেই যায়; বকেয়া পেলে আয়ে আসে।': 'Lending shows as money out, borrowing as money in — not an expense or income, just money moving. Project spending is deducted from here; dues collected count as income.',
  'এর পরের লেনদেন · {0}টা': 'Transactions since · {0}',
  '{0}: প্রতি মাসের {1} তারিখে মনে করাব': '{0}: I’ll remind you on day {1} of every month',
  'কোন বিল দেন? চাপ দিয়ে তারিখ দিন — প্রতি মাসে মনে করাব।': 'Which bills do you pay? Tap one and choose a day — I’ll remind you every month.',
  'মাসের বিলগুলো মনে করাব': 'I’ll remind you of monthly bills',
  'বাঁ দিকে টানলে মুছে যায় · চাপলে বদলানো যায় · চেপে ধরলে কয়েকটা বাছাই': 'Swipe left to delete · tap to edit · long-press to select several',
  'বলুন বা লিখুন — রেখে দেব, খুঁজে দেব, উত্তর দেব': 'Speak or type — I’ll save it, find it, or answer it',
  'বলছি — আপনি কথা বললেই থেমে শুনব': 'Speaking — talk and I’ll stop to listen',
  'রাখা হয়েছে। {0}': 'Saved. {0}',
  'লেনদেন বদলান': 'Edit transaction',
  'দিলে আগের দিন আর সেদিন সকালে মনে করাব': 'If set, I’ll remind you the day before and that morning',
  'রাখলে {0}: ': 'If you save {0}: ',
  'প্রতিদিন {0}-এ জিজ্ঞেস করব — টিক দেওয়া থাকলে করব না': 'I’ll ask every day at {0} — unless it’s already checked off',
  'প্রতিদিন টিক দিন — টানা কত দিন হলো দেখাবে, চাইলে রোজ নির্দিষ্ট সময়ে মনে করাব।': 'Tick it every day — see your streak, and get a daily reminder at a set time if you like.',
  'পরিবারে যুক্ত থাকলে ওঁর ফোনে বাজবে — তালাবদ্ধ হয়ে যায়': 'If they’re in your family, it rings on their phone — sent encrypted',
  'ওষুধের নাম, দিনে কয়বার আর কয়টা আছে লিখুন — সময়মতো বাজবে, খেলে টিক দিন, ফুরানোর আগে মনে করাব।': 'Enter the name, how often, and how many you have — it rings on time, you tick it off when taken, and I’ll remind you before it runs out.',
  'দিলে ফুরানোর আগে মনে করাব': 'If set, I’ll remind you before it runs out',
  'কাকে দেব (নাম)': 'Who I owe (name)',
  'আগের দিন আর সেদিন সকাল ১০টায় মনে করিয়ে দেব।': 'I’ll remind you the day before and on the day at 10 am.',
  'বকেয়া পাব {0}': 'Owed to me {0}',
  'বকেয়া দেব {0}': 'I owe {0}',
  'ধার-দেনার মতোই: কেউ বাকিতে নিলে বা আপনি বাকিতে নিলে লিখুন — কে, কী, কত টাকা, কবে শোধ। সেদিন মনে করিয়ে দেব।': 'Just like loans: when someone buys on credit from you, or you buy on credit, record it here — who, what, how much and when it’s due. I’ll remind you on the day.',
  'এনক্রিপ্ট করা · {0}টা তথ্য': 'Encrypted · {0} items',
  'পাসপোর্ট, ড্রাইভিং লাইসেন্স, ট্রেড লাইসেন্স — ডকুমেন্ট খুলে মেয়াদ শেষের তারিখ দিন। ৬ মাস আগে, ১ মাস আগে আর শেষের দিন মনে করাব।': 'Passport, driving license, trade license — open the document and set its expiry date. I’ll remind you 6 months before, 1 month before, and on the day.',
  '{0}টা ডকুমেন্টে মেয়াদ দেওয়া নেই': '{0} documents have no expiry date',
  'আবার দিতে পারবেন {0} থেকে ({1}) — সেদিন সকালে মনে করাব।': 'You can donate again from {0} ({1}) — I’ll remind you that morning.',
  'পাব / বকেয়া': 'Owed to me / dues',
  'পরিবারে যুক্ত হতে আগে Google দিয়ে লগইন করুন — সবাই নিজের ইমেইলে যুক্ত হন।': 'Sign in with Google first to use Family — each member joins with their own email.',
  'পরিবার থেকে এসেছে': 'Received from family',
  '{0} আপনাকে পরিবারে যুক্ত করতে চান': '{0} wants to add you to their family',
  'আমার পরিবার': 'My family',
  'My Assistant আপনার ফোনের লোকেশন নেয় শুধু তখন, যখন অ্যাপ ব্যবহারের সময় আপনি যাঁদের অনুমতি দিয়েছেন সেই পরিবারের কেউ “এখন কোথায়?” জিজ্ঞেস করেন। লোকেশন তালাবদ্ধ হয়ে শুধু তাঁদের কাছে যায়; আমরা দেখতে পারি না, বিজ্ঞাপনে বা অন্য কিছুতে ব্যবহার হয় না। পরিবার পাতা থেকে যেকোনো সময় বন্ধ করা যায়।': 'My Assistant accesses your phone’s location only when a family member you’ve approved asks “Where now?” while the app is in use. Your location is encrypted so only they can open it; we can’t see it, and it’s never used for ads or anything else. You can turn this off on the Family page at any time.',
  'My Assistant আপনার ফোনের লোকেশন নেয় — অ্যাপ বন্ধ থাকলেও — শুধু তখন, যখন আপনি যাঁদের অনুমতি দিয়েছেন সেই পরিবারের কেউ “এখন কোথায়?” জিজ্ঞেস করেন (যেমন ফোন হারালে খুঁজতে)। লোকেশন তালাবদ্ধ হয়ে শুধু তাঁদের কাছে যায়; আমরা দেখতে পারি না, বিজ্ঞাপনে বা অন্য কিছুতে ব্যবহার হয় না। পরিবার পাতা থেকে যেকোনো সময় বন্ধ করা যায়।': 'My Assistant accesses your phone’s location — even when the app is closed — only when a family member you’ve allowed asks “Where now?” (for example, to find a lost phone). It’s encrypted and goes only to them; we can’t see it, and it’s never used for ads or anything else. You can turn this off on the Family page at any time.',
  'পরিবারে যোগ করুন': 'Add to family',
  'আর পরিবারে নেই': 'No longer in your family',
  'আমার ইন্তেকালের পর (কাগজ যাচাই আর ১৪ দিন পর) পরিবার পাতায় বাছাই করা অংশ দেখবেন': 'After my death (document verification plus 14 days), they can see the chosen items on the Family page',
  'পরিবার থেকে সরাবেন?': 'Remove from family?',
  'পরিবার থেকে সরান': 'Remove from family',
  'টানা কত দিন': 'Habit streaks',
  'এই ফোল্ডারে · {0}টা': 'In this folder · {0}',
  'নম্বর, নাম, জন্মতারিখ, মেয়াদ — ফোনেই পড়ে বসিয়ে দেব, আপনি মিলিয়ে নেবেন': 'Number, name, date of birth, expiry — read on the phone and filled in for you to check',
  'দিলে ৬ মাস আগে, এক মাস আগে আর শেষের দিন মনে করাব': 'If set, I’ll remind you 6 months before, 1 month before and on the expiry date',
  '৬ মাস আগে, এক মাস আগে আর শেষের দিন মনে করাব': 'I’ll remind you 6 months before, 1 month before and on the expiry date',
  '{0}টা দোকান মিলিয়ে': '{0} shops combined',
  '{0}টা বিক্রি': '{0} sales',
  'রসিদ · {0}টা': 'Receipts · {0}',
  'গ্রাহকের বাকি · {0} জন': 'Customer dues · {0}',
  'মনে করিয়ে দিন': 'Payment reminder',
  'হোয়াটসঅ্যাপে পাঠান': 'Send on WhatsApp',
  'আমার তথ্য': 'My Data',
  'পাব · {0} জনের কাছে': 'Owed to me ({0})',
  'দেব · {0} জনকে': 'I owe ({0})',
  'হোয়াটসঅ্যাপ খোলা গেল না': 'Couldn’t open WhatsApp',
  'বাংলাদেশের ইপিআই সময়সূচি অনুযায়ী। প্রতিটা টিকার আগের দিন আর সেদিন সকালে মনে করাব। টিকা কার্ডের তারিখের সাথে মিলিয়ে নিন — কেন্দ্রের দেওয়া তারিখই মানবেন।': 'Based on Bangladesh’s EPI schedule. I’ll remind you the day before each vaccine and that morning. Always check against the vaccination card — the date your center gives takes priority.',
  'পাঠান (হোয়াটসঅ্যাপ ইত্যাদি)': 'Share (WhatsApp, etc.)',
  'DPS, লোনের কিস্তি, বীমার প্রিমিয়াম — প্রতি মাসে আগের দিন মনে করাব, টিক দিলে কত বাকি দেখাবে।': 'DPS, loan installments, insurance premiums — I’ll remind you the day before, every month; tick each one to see what’s left.',
  '{0}/{1} কিস্তি দেওয়া ({2}) · বাকি {3}টা · শেষ {4}': '{0}/{1} installments paid ({2}) · {3} left · ends {4}',
  'একমত না হলে, দরকার হলে আমাদের সার্ভার থেকে তৃতীয় একটা মত নেওয়া হয় — নাম সরিয়ে। তিনজনের দুজন যা বলে, সেটাই। পাসওয়ার্ড, মোবাইল নম্বর, কোড বা স্বাস্থ্য-ওষুধের কথা থাকলে কখনো বাইরে যায় না — ফোনেই সিদ্ধান্ত হয়।': 'When they don’t, a third opinion may be requested from our server — with names removed — and the majority decides. Anything involving passwords, phone numbers, codes, health or medicines is never sent; the phone decides on its own.',
  'যেসব কথায় নিয়ম আর মডেল একমত হয়নি, তার কিছু নাম সরিয়ে সার্ভারে আসে। পাসওয়ার্ড, মোবাইল নম্বর, কোড, স্বাস্থ্য বা ওষুধের কথা কখনো না; ১৮০ দিন পর নিজে মুছে যায়।': 'Some sentences that the rules and the model read differently are sent to the server with names removed. Never passwords, phone numbers, codes, health or medicines; automatically deleted after 180 days.',
  'টাকার অঙ্কটা ধরতে পারিনি। আবার বলুন, বা লিখে দিন।': 'I didn’t catch the amount. Say it again, or type it.',
  'নামটা ধরতে পারিনি। আবার বলুন, বা লিখে দিন।': 'I didn’t catch the name. Say it again, or type it.',
